window.TADABBUR_FUSSILAT = {"_meta":{"description":"تدبّر سورة فصّلت (٤١)، وسورةٌ مكّيّةٌ من الحواميم، تُسمّى فصّلت والسجدةَ وحم السجدة. محورُها تعظيمُ القرآنِ المفصَّلِ وإعراضُ المشركين عنه، وآياتُ خلقِ السماواتِ والأرضِ في ستّةِ أيام، وعاقبةُ عادٍ وثمود، وشهادةُ الجوارحِ على أصحابها يومَ القيامة، والوصيّةُ بدفعِ السيّئةِ بالتي هي أحسن، وأنّ القرآنَ هدًى وشفاءٌ للمؤمنين، وآياتُ الله في الآفاقِ والأنفس. فيها «قرآنا عربيا لقوم يعلمون بشيرا ونذيرا فأعرض أكثرهم»، ووصيّةُ الاستقامة «إن الذين قالوا ربنا الله ثم استقاموا تتنزل عليهم الملائكة»، و«ادفع بالتي هي أحسن»، وختامُها «سنريهم آياتنا في الآفاق وفي أنفسهم حتى يتبين لهم أنه الحق».","honesty":"كلُّ وقفةٍ مُسنَدةٌ إلى تفسيرٍ معتمد (ابن كثير/السعدي) وموسومةٌ بدرجتها. حالُ القلبِ والعملُ اجتهاديٌّ موسوم. لا يُقدَّم شيءٌ على أنه إعجازٌ مثبت."},"n":41,"name":"فصّلت","total_ayahs":54,"audio":[1,6,30,33,34,37,44,49,53,54],"passages":[{"title":"تنزيلُ القرآنِ المفصَّلِ وإعراضُهم، والدعوةُ إلى الاستقامةِ والاستغفار","range":[1,8],"theme":"أنّ القرآنَ تنزيلٌ من الرحمنِ الرحيمِ فُصّلت آياته بشيرًا ونذيرًا فأعرض أكثرهم وحجبوا قلوبهم عنه، وأمرُ النبيِّ أن يعلن بشريّته وأنّ الإله واحدٌ فليستقيموا إليه ويستغفروه، وويلٌ للمشركين الذين لا يؤتون الزكاةَ وهم بالآخرةِ كافرون، وأنّ للمؤمنين العاملين أجرًا غيرَ ممنون","verses":[{"n":1,"reflection":{"text":"«حم»: حروفٌ مقطّعةٌ افتُتِحت بها السورةُ (من الحواميم)، من المتشابهِ الذي استأثر الله بعلمِ المرادِ منه، ويُشار بها إلى إعجازِ القرآنِ المؤلَّفِ من جنسِ هذه الحروف؛ ففي هذا تنبيهٌ على عظمةِ القرآن؛ فسلّم لما استأثر الله بعلمه، وتدبّر ما بيّنه لك، فالتسليمُ فيما لم تعلم من صفاتِ الراسخين.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"التسليمُ لله فيما استأثر بعلمه، والتدبّرُ لما بيّن."},"action":{"text":"اعلم أنّ سورةَ فصّلت افتُتِحت بـ«حم» من الحروفِ المقطّعةِ التي افتُتِحت بها الحواميم، وهي من المتشابهِ الذي استأثر الله بعلمِ المرادِ منه «حم»؛ وأصحُّ ما قيل فيها الإشارةُ إلى إعجازِ القرآن: فهذا الكتابُ المعجزُ مؤلَّفٌ من جنسِ هذه الحروفِ التي تعرفونها، ومع ذلك عجزتم عن معارضته؛ فسلّم لما استأثر الله بعلمه من المتشابه؛ وتدبّر واعمل بما بيّنه لك من المحكم؛ فالراسخون في العلمِ يقولون آمنّا به كلٌّ من عند ربنا؛ فاجعل تسليمك لله فيما لم تعلم علامةَ إيمانك؛ ولا تتكلّف الخوضَ فيما لا سبيلَ لك إلى علمه؛ بل آمن بالمتشابه، واعمل بالمحكم؛ فبالتسليمِ والعملِ تُنال الهداية."}},{"n":2,"reflection":{"text":"«تنزيل من الرحمن الرحيم»: هذا القرآنُ منزّلٌ من الرحمنِ الرحيمِ الواسعِ الرحمة؛ ففي هذا بيانُ أنّ القرآنَ من رحمةِ الله؛ فاعلم أنّ القرآنَ رحمةٌ من الرحمنِ الرحيم، فاستقبله بالشكرِ والفرح، فأعظمُ رحمةٍ أنزلها الله القرآن، فاعتنِ به تلاوةً وتدبّرًا وعملًا، شاكرًا رحمةَ الله بإنزاله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الفرحُ بالقرآنِ وشكرُه، فهو رحمةٌ من الرحمنِ الرحيم."},"action":{"text":"اعلم أنّ هذا القرآنَ منزّلٌ من الرحمنِ الرحيم، الذي وسعت رحمته كلَّ شيء «تنزيل من الرحمن الرحيم»؛ فوصف الله نفسه بالرحمنِ الرحيمِ عند ذكرِ إنزالِ القرآن، ليُعلَم أنّ القرآنَ من أعظمِ آثارِ رحمته بعباده؛ ففي هذا بيانُ أنّ القرآنَ رحمةٌ عظيمةٌ من الله؛ فبه هدى الله من الضلالة، وبصّر من العمى، وأنقذ من الجهالة؛ يا أيها الناسُ قد جاءتكم موعظةٌ من ربكم وشفاءٌ لما في الصدورِ وهدًى ورحمة؛ فاستقبل القرآنَ بالشكرِ والفرح؛ قل بفضلِ الله وبرحمته فبذلك فليفرحوا؛ فأعظمُ رحمةٍ أنزلها الله على العبادِ القرآن؛ فاعتنِ به تلاوةً وتدبّرًا وعملًا وتحكيمًا؛ واشكر الله على نعمةِ القرآنِ التي هي من رحمته؛ فمن عرف أنّ القرآنَ رحمةٌ من الله أقبل عليه وشكره؛ فاجعل قلبك ممتلئًا بشكرِ رحمةِ الله بإنزالِ القرآن؛ فبالإقبالِ عليه والعملِ به تُنال رحمةُ الله."}},{"n":3,"reflection":{"text":"«كتاب فصلت آياته قرآنا عربيا لقوم يعلمون»: كتابٌ بُيّنت آياته وفُصّلت أحكامه، قرآنًا عربيًّا واضحًا لقومٍ يعلمون وينتفعون؛ ففي هذا بيانُ وضوحِ القرآنِ وتفصيلِه؛ فاعلم أنّ القرآنَ مفصَّلٌ واضحٌ لمن طلب العلم، فاطلب العلمَ لتنتفع بالقرآن، فالقرآنُ يُفهَم ويُنتفَع به لأهلِ العلم، فتعلّم لتفقه آياته.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"طلبُ العلمِ للانتفاعِ بالقرآنِ المفصَّلِ الواضح."},"action":{"text":"اعلم أنّ القرآنَ كتابٌ فُصّلت آياته وبُيّنت أحكامه ومعانيه وأخباره تفصيلًا واضحًا، قرآنًا عربيًّا بلسانٍ عربيٍّ مبين، لقومٍ يعلمون وينتفعون به «كتاب فصلت آياته قرآنا عربيا لقوم يعلمون»؛ ففي هذا بيانُ وضوحِ القرآنِ وتفصيلِ آياته؛ فآياته مفصّلةٌ مبيّنةٌ: فصّل فيها الحلالَ والحرام، والوعدَ والوعيد، والأمرَ والنهي، والقصصَ والأمثال؛ فاعلم أنّ القرآنَ مفصَّلٌ واضحٌ لمن طلب العلمَ وأقبل عليه بفهم؛ فاطلب العلمَ النافعَ لتنتفع بالقرآنِ وتفقه آياته؛ فالقرآنُ يُفهَم ويُنتفَع به لأهلِ العلمِ والفهم؛ إنما يخشى الله من عباده العلماء؛ فتعلّم علمَ القرآنِ والدين؛ وتدبّر آياته المفصّلة؛ فمن طلب العلمَ فهم القرآنَ وانتفع به؛ ومن أعرض عن العلمِ حُرِم فهمه والانتفاعَ به؛ فاجعل طلبَ العلمِ وتدبّرَ القرآنِ همّك؛ فبالعلمِ تُفهَم آياتُ القرآنِ المفصّلة، ويُنتفَع بهداياتها."}},{"n":4,"reflection":{"text":"«بشيرا ونذيرا فأعرض أكثرهم فهم لا يسمعون»: القرآنُ بشيرٌ للمؤمنين ونذيرٌ للكافرين، فأعرض أكثرهم فهم لا يسمعون سماعَ قبول؛ ففي هذا بيانُ وظيفةِ القرآنِ وإعراضِ الأكثرين؛ فكن ممّن يسمع القرآنَ سماعَ قبولٍ وانتفاع، ولا تكن من المعرضين، فالبشارةُ والنذارةُ فيه، فاستمع للقرآنِ لتنال بشارته وتتّقيَ نذارته.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"سماعُ القرآنِ سماعَ قبولٍ وانتفاع، وتركُ الإعراض."},"action":{"text":"اعلم أنّ القرآنَ بشيرٌ يبشّر المؤمنين المطيعين بالثوابِ والجنّة، ونذيرٌ يحذّر الكافرين العاصين من العقابِ والنار؛ فأعرض أكثرُ الناسِ عنه، فهم لا يسمعونه سماعَ قبولٍ وتدبّرٍ وانتفاع، وإن سمعوه بآذانهم «بشيرا ونذيرا فأعرض أكثرهم فهم لا يسمعون»؛ ففي هذا بيانُ وظيفةِ القرآنِ في البشارةِ والنذارة، وذمُّ إعراضِ الأكثرين عنه؛ فكن ممّن يسمع القرآنَ سماعَ قبولٍ وتدبّرٍ وانتفاع؛ لا سماعَ إعراضٍ وغفلة؛ فالسماعُ النافعُ سماعُ القلبِ لا مجرّدُ الأذن؛ والذين إذا ذُكِّروا بآياتِ ربهم لم يخرّوا عليها صمًّا وعميانًا؛ فلا تكن من المعرضين الذين يسمعون القرآنَ بآذانهم وقلوبهم عنه لاهية؛ بل استمع للقرآنِ بقلبٍ حاضرٍ متدبّرٍ منتفع؛ لتنال بشارته إن أطعت، وتتّقيَ نذارته إن حُذّرت؛ فمن سمع القرآنَ سماعَ قبولٍ انتفع به واهتدى؛ ومن أعرض عنه حُرِم خيره؛ فاجعل سماعك للقرآنِ سماعَ إقبالٍ وقبولٍ وعمل."}},{"n":5,"reflection":{"text":"«وقالوا قلوبنا في أكنة مما تدعونا إليه وفي آذاننا وقر ومن بيننا وبينك حجاب فاعمل إننا عاملون»، وقالوا: قلوبنا في أغطيةٍ عمّا تدعونا إليه، وفي آذاننا صمم، وبيننا وبينك حاجز، فاعمل على دينك إننا عاملون على ديننا؛ ففي هذا إعراضُ المشركين وإصرارهم على الكفر؛ فاحذر أن تجعل بينك وبين الحقِّ حجابًا بالإعراضِ والإصرار، فافتح قلبك للحقِّ ولا تحجبه عنه، فالإعراضُ عن الحقِّ يحجب القلبَ عنه.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"فتحُ القلبِ للحق، والحذرُ من حجبِه عنه بالإعراض."},"action":{"text":"تأمّل إعراضَ المشركين وإصرارهم: قالوا للنبيِّ ﷺ: قلوبنا في أكنّةٍ وأغطيةٍ عمّا تدعونا إليه من التوحيدِ فلا نفقهه، وفي آذاننا صممٌ ووقرٌ فلا نسمعه، ومن بيننا وبينك حجابٌ وحاجزٌ يمنعنا من اتّباعك؛ فاعمل أنت على دينك، إننا عاملون على ديننا «وقالوا قلوبنا في أكنة مما تدعونا إليه وفي آذاننا وقر ومن بيننا وبينك حجاب فاعمل إننا عاملون»؛ ففي هذا إعراضُ المشركين وإصرارهم على الكفر، ومقاطعتهم للنبيِّ ودعوته؛ فحجبوا قلوبهم وآذانهم عن الحقِّ بإعراضهم وإصرارهم؛ فاحذر أن تجعل بينك وبين الحقِّ حجابًا بالإعراضِ عنه والإصرارِ على ضدّه؛ فإنّ الإعراضَ المستمرَّ عن الحقِّ يطبع على القلبِ ويحجبه عنه؛ بل ران على قلوبهم ما كانوا يكسبون؛ فافتح قلبك للحقِّ، واستمع إليه بقلبٍ منفتح؛ ولا تحجب قلبك وسمعك عن الحقِّ بالكِبرِ والإعراض؛ فمن فتح قلبه للحقِّ اهتدى، ومن حجبه عنه بالإعراضِ ضلّ؛ فلا تكن كهؤلاء الذين جعلوا بينهم وبين الحقِّ حجابًا؛ بل أقبل على الحقِّ بقلبك وسمعك؛ فبالإقبالِ على الحقِّ يُفتَح القلبُ للهداية."}},{"n":6,"reflection":{"text":"«قل إنما أنا بشر مثلكم يوحى إلي أنما إلهكم إله واحد فاستقيموا إليه واستغفروه وويل للمشركين»: قل إنما أنا بشرٌ مثلكم يوحى إليّ أنّ إلهكم واحد، فاستقيموا في التوجّهِ إليه واستغفروه، وويلٌ للمشركين؛ ففي هذا الأمرُ بالاستقامةِ والاستغفار؛ فاستقم في عبادتك وتوجّهك إلى الله، وأكثر من الاستغفار، فالاستقامةُ والاستغفارُ جماعُ الخير، فمن استقام واستغفر فاز، ومن أشرك خسر.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاستقامةُ في التوجّهِ إلى الله والإكثارُ من الاستغفار."},"action":{"text":"تأمّل ما أُمِر النبيُّ ﷺ أن يقوله: قل إنما أنا بشرٌ مثلكم في البشرية، لكن يوحى إليّ من ربي أنّ إلهكم إلهٌ واحدٌ لا شريكَ له؛ فاستقيموا في التوجّهِ إليه بالطاعةِ والإخلاص، واستغفروه من ذنوبكم وتقصيركم؛ وويلٌ وعذابٌ شديدٌ للمشركين «قل إنما أنا بشر مثلكم يوحى إلي أنما إلهكم إله واحد فاستقيموا إليه واستغفروه وويل للمشركين»؛ ففي هذا الأمرُ بالاستقامةِ على التوحيدِ والطاعة، والإكثارِ من الاستغفار؛ فاستقم في عبادتك وتوجّهك إلى الله وحده؛ فالاستقامةُ لزومُ الصراطِ المستقيمِ في الاعتقادِ والقولِ والعمل؛ إنّ الذين قالوا ربنا الله ثم استقاموا؛ وأكثر من الاستغفارِ لجبرِ ما يقع من التقصيرِ في الاستقامة؛ فالاستقامةُ والاستغفارُ متلازمان: تستقيم بجهدك، وتستغفر لتقصيرك؛ فبالاستقامةِ تنال المطلوب، وبالاستغفارِ تُمحى الذنوب؛ فمن استقام على التوحيدِ والطاعةِ وأكثر الاستغفارَ فاز؛ ومن أشرك بالله فله الويلُ والعذاب؛ فاجعل شعارك: الاستقامةَ على التوحيدِ والطاعة، والإكثارَ من الاستغفار؛ فبهما جماعُ الخيرِ والفلاح."}},{"n":7,"reflection":{"text":"«الذين لا يؤتون الزكاة وهم بالآخرة هم كافرون»: المشركون الذين لا يؤدّون الزكاة (أو لا يزكّون أنفسهم بالتوحيد) وهم بالآخرةِ كافرون؛ ففي هذا ذمُّ منعِ الزكاةِ والكفرِ بالآخرة؛ فأدِّ الزكاةَ وزكِّ نفسك بالتوحيدِ والطاعة، وآمن بالآخرة، فمنعُ الزكاةِ والكفرُ بالآخرةِ من صفاتِ المشركين، فطهّر مالك ونفسك، وآمن بالمعاد.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"أداءُ الزكاةِ وتزكيةُ النفس، والإيمانُ بالآخرة."},"action":{"text":"تأمّل وصفَ المشركين الذين توعّدهم الله بالويل: الذين لا يؤتون الزكاةَ المفروضةَ في أموالهم، ولا يزكّون أنفسهم بالتوحيدِ والإيمان، وهم بالآخرةِ والبعثِ والجزاءِ كافرون جاحدون «الذين لا يؤتون الزكاة وهم بالآخرة هم كافرون»؛ ففي هذا ذمُّ منعِ الزكاةِ والكفرِ بالآخرة؛ فجمعوا بين منعِ حقِّ المالِ والكفرِ بالبعث؛ فأدِّ الزكاةَ المفروضةَ في مالك طيّبةً بها نفسك؛ فالزكاةُ طهرةٌ للمالِ والنفس؛ خذ من أموالهم صدقةً تطهّرهم وتزكّيهم بها؛ وزكِّ نفسك بالتوحيدِ والإيمانِ والطاعةِ واجتنابِ المعاصي؛ قد أفلح من زكّاها؛ وآمن بالآخرةِ والبعثِ والجزاءِ إيمانًا يحملك على العمل؛ فالإيمانُ بالآخرةِ يبعث على أداءِ الحقوقِ والاستعدادِ للقاءِ الله؛ فاحذر أن تكون فيك خصلةٌ من صفاتِ المشركين: منعِ الزكاةِ أو ضعفِ الإيمانِ بالآخرة؛ فطهّر مالك بالزكاة، ونفسك بالتوحيدِ والطاعة، وقوِّ إيمانك بالآخرة؛ فمن أدّى الزكاةَ وزكّى نفسه وآمن بالآخرة فقد نجا من صفاتِ المشركين."}},{"n":8,"reflection":{"text":"«إن الذين آمنوا وعملوا الصالحات لهم أجر غير ممنون»: إنّ الذين آمنوا وعملوا الصالحاتِ لهم أجرٌ دائمٌ غيرُ مقطوعٍ ولا منقوص؛ ففي هذا بشارةُ المؤمنين العاملين بالأجرِ الدائم؛ فاعمل صالحًا مع الإيمانِ لتنال الأجرَ الدائمَ غيرَ المنقطع، فأجرُ المؤمنِ لا ينقطع ولا يُمَنّ به عليه، فاجتهد في الإيمانِ والعملِ الصالح.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإيمانُ والعملُ الصالح رجاءَ الأجرِ الدائمِ غيرِ المنقطع."},"action":{"text":"تأمّل بشارةَ المؤمنين، مقابلَ وعيدِ المشركين: إنّ الذين آمنوا بالله وعملوا الصالحاتِ لهم أجرٌ غيرُ ممنون، أي دائمٌ لا ينقطع، ولا مقطوعٌ ولا منقوص، ولا يُمَنّ به عليهم «إن الذين آمنوا وعملوا الصالحات لهم أجر غير ممنون»؛ ففي هذا بشارةُ المؤمنين العاملين للصالحاتِ بالأجرِ الدائمِ الكامل؛ فأجرهم في الجنّةِ دائمٌ لا ينقطع، خالصٌ لا يُنغّصه منٌّ ولا أذًى؛ عطاءً غيرَ مجذوذ؛ لهم ما يشاؤون فيها ولدينا مزيد؛ فاعمل صالحًا مع الإيمانِ لتنال هذا الأجرَ الدائمَ غيرَ المنقطع؛ فشرطُ قبولِ العملِ الصالحِ الإيمان؛ فاجمع بين الإيمانِ والعملِ الصالح؛ فأجرُ المؤمنِ العاملِ لا ينقطع في الآخرة، بخلافِ نعيمِ الدنيا الزائل؛ فاجتهد في الإيمانِ والعملِ الصالحِ لتفوز بالأجرِ الدائم؛ فما عند الله خيرٌ وأبقى؛ فاعمل للأجرِ الباقي، لا للمتاعِ الفاني؛ فمن آمن وعمل صالحًا فله أجرٌ دائمٌ في جنّاتِ النعيم؛ فاجعل همّك الإيمانَ والعملَ الصالحَ رجاءَ الأجرِ غيرِ الممنون."}}]},{"title":"آياتُ خلقِ الأرضِ والسماواتِ في ستّةِ أيام، وانقيادُ الكونِ لله","range":[9,12],"theme":"الإنكارُ على من يكفر بخالقِ الأرضِ ويجعل له أندادًا، وخلقُ الأرضِ ورواسيها وتقديرُ أقواتها، والاستواءُ إلى السماءِ وهي دخانٌ فأتت هي والأرضُ طائعتين، وقضاؤها سبعَ سماواتٍ وتزيينُ الدنيا بالمصابيحِ وحفظُها، ذلك تقديرُ العزيزِ العليم","verses":[{"n":9,"reflection":{"text":"«قل أئنكم لتكفرون بالذي خلق الأرض في يومين وتجعلون له أندادا ذلك رب العالمين»: قل: أتكفرون بالذي خلق الأرضَ في يومين وتجعلون له أندادًا؟ ذلك ربُّ العالمين؛ ففي هذا الإنكارُ على من يكفر بالخالقِ ويجعل له أندادًا؛ فوحّد الخالقَ العظيمَ الذي خلق الأرض، ولا تجعل له ندًّا ولا شريكًا، فمن خلق الأرضَ يستحقّ العبادةَ وحده، فأخلص له العبادةَ ولا تشرك.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"توحيدُ الخالقِ العظيم، وتركُ جعلِ الأندادِ له."},"action":{"text":"تأمّل الإنكارَ على المشركين: قل لهم منكرًا: أئنكم لتكفرون بالله الذي خلق الأرضَ في يومين، من أيّامِ الله، وتجعلون له أندادًا وأشباهًا تعبدونها معه؟ ذلك الخالقُ العظيمُ هو ربُّ العالمين وخالقهم ومدبّرهم «قل أئنكم لتكفرون بالذي خلق الأرض في يومين وتجعلون له أندادا ذلك رب العالمين»؛ ففي هذا الإنكارُ الشديدُ على من يكفر بالخالقِ العظيمِ ويجعل له أندادًا؛ فكيف يُكفَر بمن خلق الأرضَ العظيمة، ويُجعَل له شركاء؟ فوحّد الخالقَ العظيمَ الذي خلق الأرضَ وما فيها؛ ولا تجعل له ندًّا ولا شريكًا ولا شبيهًا؛ فلا تجعلوا لله أندادًا وأنتم تعلمون؛ فمن خلق الأرضَ والعالمين يستحقّ العبادةَ وحده؛ فأفرده بالعبادةِ كما تفرّد بالخلق؛ فأخلص له العبادةَ، ولا تشرك به شيئًا؛ فتأمّل في خلقِ الأرضِ وعظمتها؛ فمن خلقها هو ربّك المستحقُّ للعبادة؛ فكيف تعبد معه غيره؟ فوحّد ربَّ العالمين خالقَ الأرضِ والسماوات؛ ولا تجعل له أندادًا من خلقه؛ فالتوحيدُ حقُّ الخالقِ العظيم."}},{"n":10,"reflection":{"text":"«وجعل فيها رواسي من فوقها وبارك فيها وقدر فيها أقواتها في أربعة أيام سواء للسائلين»، وجعل في الأرضِ جبالًا ثوابتَ من فوقها، وبارك فيها، وقدّر فيها أقواتَ أهلها في أربعةِ أيامٍ كاملةٍ للسائلين عن ذلك؛ ففي هذا تعدادُ نعمِ الله في الأرض؛ فتأمّل نعمَ الله في الجبالِ والبركةِ والأرزاقِ المقدّرة، واشكرها، فمن دبّر الأرضَ ورزقها يستحقّ العبادة، فاشكر المدبّرَ ووحّده.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"شكرُ نعمِ الله في تدبيرِ الأرضِ وأرزاقها، وتوحيدُ المدبّر."},"action":{"text":"تأمّل نعمَ الله في الأرض: وجعل فيها رواسيَ، جبالًا ثوابتَ، من فوقها لتثبت ولا تميد بأهلها، وبارك فيها فكثّر خيرها ومنافعها، وقدّر فيها أقواتَ أهلها من الزروعِ والثمارِ والمعادن، وقدّر لكلِّ بلدٍ ما يصلح له؛ كلُّ ذلك في أربعةِ أيامٍ كاملةٍ (بضمّها إلى اليومين)، بيانًا شافيًا للسائلين عن كيفيةِ الخلق «وجعل فيها رواسي من فوقها وبارك فيها وقدر فيها أقواتها في أربعة أيام سواء للسائلين»؛ ففي هذا تعدادُ نعمِ الله في تدبيرِ الأرضِ وأرزاقها؛ فتأمّل نعمَ الله في الجبالِ التي تثبّت الأرض، والبركةِ التي جعلها فيها، والأقواتِ والأرزاقِ التي قدّرها لأهلها؛ فمن دبّر الأرضَ بهذه الحكمةِ والإتقان، وقدّر فيها الأرزاق، يستحقّ العبادةَ والشكر؛ فاشكر الله على نعمِه في الأرضِ وتدبيرِها وأرزاقها؛ واستشعر حكمةَ الله في خلقِ الجبالِ وتقديرِ الأقوات؛ فمن تأمّل نعمَ الله في الأرضِ شكرها ووحّد المدبّر؛ فاجعل تأمّلك في خلقِ الأرضِ وأرزاقها سبيلًا لشكرِ الله وتوحيده وعبادته."}},{"n":11,"reflection":{"text":"«ثم استوى إلى السماء وهي دخان فقال لها وللأرض ائتيا طوعا أو كرها قالتا أتينا طائعين»: ثم قصد إلى خلقِ السماءِ وهي دخان، فقال لها وللأرض: انقادا لأمري طوعًا أو كرهًا، قالتا: أتينا طائعين؛ ففي هذا انقيادُ السماواتِ والأرضِ لأمرِ الله؛ فاعلم أنّ الكونَ كلَّه منقادٌ لله طوعًا، فكن أنت أولى بالانقيادِ الطوعيِّ لأمرِ الله، فالسماواتُ والأرضُ أتت طائعةً، فأت أنت طائعًا لأمرِ الله.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الانقيادُ الطوعيُّ لأمرِ الله، اقتداءً بالسماواتِ والأرض."},"action":{"text":"تأمّل انقيادَ الكونِ لأمرِ الله: ثم استوى وقصد سبحانه إلى خلقِ السماءِ وهي دخان، فقال للسماءِ وللأرض: ائتيا وانقادا لأمري وما أريده منكما، طوعًا أو كرهًا، فقالتا: أتينا طائعين منقادين مختارين «ثم استوى إلى السماء وهي دخان فقال لها وللأرض ائتيا طوعا أو كرها قالتا أتينا طائعين»؛ ففي هذا انقيادُ السماواتِ والأرضِ التامُّ لأمرِ الله طوعًا؛ فما امتنعتا ولا تأبّتا، بل أتتا طائعتين منقادتين؛ فاعلم أنّ الكونَ كلَّه، علويّه وسفليّه، منقادٌ لله خاضعٌ لأمره؛ وله أسلم من في السماواتِ والأرضِ طوعًا وكرهًا؛ فكن أنت، أيها الإنسانُ المكرّمُ المخيَّر، أولى بالانقيادِ الطوعيِّ الاختياريِّ لأمرِ الله؛ فإذا كانت السماواتُ والأرضُ الجماداتُ أتت طائعةً منقادة، فأنت أولى بالطاعةِ والانقيادِ عن رغبةٍ ومحبّة؛ فأت أمرَ الله طائعًا مختارًا، لا مكرهًا مضطرًّا؛ فانقد لأمرِ الله بالطاعةِ والتسليمِ والرضا؛ فمن انقاد لله طوعًا كمّل عبوديته؛ فاجعل انقيادك لله طوعيًّا محبًّا، اقتداءً بالكونِ المنقادِ الطائع."}},{"n":12,"reflection":{"text":"«فقضاهن سبع سماوات في يومين وأوحى في كل سماء أمرها وزينا السماء الدنيا بمصابيح وحفظا ذلك تقدير العزيز العليم»: فأتمّهنّ سبعَ سماواتٍ في يومين، وأوحى في كلِّ سماءٍ أمرها، وزيّنّا السماءَ الدنيا بالنجومِ وحفظًا من الشياطين، ذلك تقديرُ العزيزِ العليم؛ ففي هذا تمامُ خلقِ السماواتِ وتزيينِها؛ فتأمّل عظمةَ خلقِ السماواتِ السبعِ وتزيينِها، فمن قدّر هذا بعزّتِه وعلمِه يستحقّ العبادة، فعظّم الخالقَ العزيزَ العليمَ ووحّده.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تعظيمُ الخالقِ العزيزِ العليم بالتأمّلِ في خلقِ السماوات."},"action":{"text":"تأمّل تمامَ خلقِ السماواتِ وتزيينها: فأتمّ الله السماواتِ وجعلهنّ سبعَ سماواتٍ في يومين، وأوحى وقدّر في كلِّ سماءٍ ما أراد فيها من الملائكةِ والأمرِ والتدبير؛ وزيّن السماءَ الدنيا، القريبةَ، بمصابيحَ من النجومِ والكواكب، وحفظًا لها من الشياطينِ المسترقةِ للسمع؛ ذلك التقديرُ المحكمُ تقديرُ العزيزِ الغالبِ العليمِ بكلِّ شيء «فقضاهن سبع سماوات في يومين وأوحى في كل سماء أمرها وزينا السماء الدنيا بمصابيح وحفظا ذلك تقدير العزيز العليم»؛ ففي هذا تمامُ خلقِ السماواتِ السبعِ وتزيينِها وحفظِها؛ فتأمّل عظمةَ خلقِ السماواتِ السبع، وتزيينِها بالنجوم، وحفظِها من الشياطين؛ فمن قدّر هذا الخلقَ العظيمَ المحكمَ بعزّتِه وعلمِه يستحقّ العبادةَ والتعظيم؛ فعظّم الخالقَ العزيزَ العليمَ في قلبك؛ وتأمّل في السماواتِ ونجومها وإحكامها؛ فمن نظر في السماءِ وتزيينها عرف عظمةَ خالقها؛ الذي خلق سبعَ سماواتٍ طباقًا ما ترى في خلقِ الرحمنِ من تفاوت؛ فوحّد الخالقَ العزيزَ العليم؛ واعبده وحده؛ فمن تأمّل خلقَ السماواتِ عظّم خالقها ووحّده."}}]},{"title":"صاعقةُ عادٍ وثمود، ونجاةُ المؤمنين المتّقين","range":[13,18],"theme":"إنذارُ المعرضين بصاعقةٍ مثلِ صاعقةِ عادٍ وثمود، ومجيءُ الرسلِ إليهم بالتوحيدِ ورفضُهم بشريّتهم، واستكبارُ عادٍ بقوّتهم وإهلاكُهم بريحٍ صرصرٍ عذابَ خزيٍ في الدنيا، وإيثارُ ثمودَ العمى على الهدى فأخذتهم صاعقةُ العذابِ الهون، ونجاةُ المؤمنين المتّقين","verses":[{"n":13,"reflection":{"text":"«فإن أعرضوا فقل أنذرتكم صاعقة مثل صاعقة عاد وثمود»: فإن أعرضوا عن التوحيدِ فقل: أنذرتكم عذابًا مهلكًا مثلَ ما أصاب عادًا وثمودَ؛ ففي هذا إنذارُ المعرضين بعذابِ الأممِ السابقة؛ فاحذر الإعراضَ عن الحقِّ الذي عاقبتُه العذابُ كعادٍ وثمود، فاتّعظ بعاقبةِ المعرضين، ولا تعرض عن الحقِّ فيصيبك ما أصابهم.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الإعراضِ عن الحق، والاتّعاظُ بعاقبةِ عادٍ وثمود."},"action":{"text":"تأمّل إنذارَ الله للمعرضين: فإن أعرض هؤلاء المشركون عن التوحيدِ والحقِّ بعد هذا البيان، فقل لهم منذِرًا: أنذرتكم وحذّرتكم عذابًا مهلكًا وصاعقةً مثلَ صاعقةِ عادٍ قومِ هودٍ وثمودَ قومِ صالح، التي أهلكتهم بإعراضهم «فإن أعرضوا فقل أنذرتكم صاعقة مثل صاعقة عاد وثمود»؛ ففي هذا إنذارُ المعرضين عن الحقِّ بعذابِ الأممِ السابقةِ المكذّبة؛ فاحذر الإعراضَ عن الحقِّ والتوحيدِ الذي عاقبتُه العذابُ والهلاك؛ فقد أُهلِكت عادٌ وثمودُ بإعراضهم وتكذيبهم؛ فاتّعظ بعاقبةِ المعرضين المكذّبين؛ ولا تعرض عن الحقِّ فيصيبك ما أصابهم من العذاب؛ فمن أعرض عن الحقِّ عرّض نفسه لعقوبةِ الله؛ فبادر بقبولِ الحقِّ والإيمانِ به؛ ولا تسلك سبيلَ المعرضين الهالكين؛ فاجعل من صاعقةِ عادٍ وثمودَ عبرةً تحملك على الإيمانِ واجتنابِ الإعراض؛ فمن اتّعظ بعاقبةِ الأممِ سلم، ومن أعرض كإعراضهم هلك كهلاكهم؛ فاتّعظ، وأقبل على الحق، واحذر الإعراض."}},{"n":14,"reflection":{"text":"«إذ جاءتهم الرسل من بين أيديهم ومن خلفهم ألا تعبدوا إلا الله قالوا لو شاء ربنا لأنزل ملائكة فإنا بما أرسلتم به كافرون»: حين جاءتهم الرسلُ من كلِّ جهةٍ يدعونهم ألا يعبدوا إلا الله، قالوا: لو شاء ربّنا لأنزل ملائكة، فإنا بما أُرسِلتم به كافرون؛ ففي هذا اعتراضُ المكذّبين على بشريةِ الرسلِ وكفرهم؛ فاحذر ردَّ الحقِّ بالاعتراضاتِ الواهية، فآمن بالرسلِ من البشرِ الذين أرسلهم الله، فردُّ الحقِّ لبشريةِ الرسلِ حجّةٌ باطلة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإيمانُ بالرسل، وتركُ ردِّ الحقِّ بالاعتراضاتِ الواهية."},"action":{"text":"تأمّل دعوةَ الرسلِ وردَّ المكذّبين: حين جاءت عادًا وثمودَ الرسلُ من بين أيديهم ومن خلفهم، أي من كلِّ جهةٍ وبكلِّ وسيلة، متتابعين، يدعونهم ألا تعبدوا إلا الله وحده؛ قالوا معترضين: لو شاء ربّنا أن يرسل رسولًا لأنزل ملائكةً لا بشرًا مثلنا، فإنا بما أُرسِلتم به من التوحيدِ كافرون جاحدون «إذ جاءتهم الرسل من بين أيديهم ومن خلفهم ألا تعبدوا إلا الله قالوا لو شاء ربنا لأنزل ملائكة فإنا بما أرسلتم به كافرون»؛ ففي هذا اعتراضُ المكذّبين على بشريةِ الرسلِ وكفرهم بما جاؤوا به؛ فردّوا الحقَّ بحجّةٍ واهيةٍ: أنّ الرسولَ ينبغي أن يكون ملَكًا لا بشرًا؛ فاحذر ردَّ الحقِّ بالاعتراضاتِ الواهيةِ والشبهاتِ الباطلة؛ فآمن بالرسلِ من البشرِ الذين اصطفاهم الله وأرسلهم؛ فحكمةُ الله أن يكون الرسولُ من جنسِ المرسَلِ إليهم ليأتسوا به؛ قل لو كان في الأرضِ ملائكةٌ يمشون مطمئنّين لنزّلنا عليهم من السماءِ ملَكًا رسولًا؛ فردُّ الحقِّ لبشريةِ الرسلِ حجّةٌ باطلةٌ داحضة؛ فلا تردّ الحقَّ بمثلِ هذه الاعتراضات؛ بل اقبله ببرهانه؛ فمن آمن بالرسلِ واتّبعهم اهتدى، ومن ردّهم بالشبهاتِ ضلّ؛ فآمن بالرسلِ وما جاؤوا به من الحق."}},{"n":15,"reflection":{"text":"«فأما عاد فاستكبروا في الأرض بغير الحق وقالوا من أشد منا قوة أولم يروا أن الله الذي خلقهم هو أشد منهم قوة وكانوا بآياتنا يجحدون»: فأما عادٌ فتكبّروا في الأرضِ بغيرِ حقٍّ وقالوا: من أشدُّ منا قوّة؟ أولم يروا أنّ الله الذي خلقهم أشدُّ منهم قوّة؟ وكانوا بآياتِنا يجحدون؛ ففي هذا ذمُّ الكِبرِ بالقوّةِ والاغترارِ بها؛ فاحذر الكِبرَ والاغترارَ بقوّتك، فمن فوقك أقوى منك، فالله أشدُّ قوّةً من كلِّ قويّ، فتواضع ولا تغترّ بقوّتك.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الكِبرِ والاغترارِ بالقوّة، والتواضعُ لله الأقوى."},"action":{"text":"تأمّل عاقبةَ عادٍ وسببها: فأما عادٌ فاستكبروا وتجبّروا في الأرضِ بغيرِ الحقِّ، واغترّوا بقوّتهم فقالوا مفتخرين: من أشدُّ منا قوّة؟ فردّ الله عليهم: أولم يروا ويعلموا أنّ الله الذي خلقهم هو أشدُّ منهم قوّة؟ وكانوا مع كبرهم بآياتِ الله يجحدون وينكرون «فأما عاد فاستكبروا في الأرض بغير الحق وقالوا من أشد منا قوة أولم يروا أن الله الذي خلقهم هو أشد منهم قوة وكانوا بآياتنا يجحدون»؛ ففي هذا ذمُّ الكِبرِ بالقوّةِ والاغترارِ بها وجحودِ آياتِ الله؛ فاغترّت عادٌ بقوّتها فاستكبرت وجحدت، فأهلكها الله؛ فاحذر الكِبرَ والاغترارَ بقوّتك أو مالك أو جاهك؛ فمهما بلغت من القوّةِ فالله أشدُّ منك قوّة، وهو خالقك؛ فمن أعظمُ منّا قوّة؟ أولم يروا أنّ الله الذي خلقهم هو أشدُّ منهم قوّة؛ فلا يحملنّك قوّتك على الكِبرِ والطغيانِ وجحودِ الحق؛ بل تواضع لله الأقوى، واشكر نعمةَ القوّةِ باستعمالها في طاعته؛ فمن اغترّ بقوّته واستكبر أهلكه الله بمن هو أقوى منه؛ فتواضع، ولا تغترّ بقوّةٍ زائلة؛ فالقوّةُ كلُّها لله، ومن فوق كلِّ قويٍّ أقوى منه؛ فاعرف ضعفك أمام قوّةِ الله."}},{"n":16,"reflection":{"text":"«فأرسلنا عليهم ريحا صرصرا في أيام نحسات لنذيقهم عذاب الخزي في الحياة الدنيا ولعذاب الآخرة أخزى وهم لا ينصرون»: فأرسلنا عليهم ريحًا شديدةَ البردِ والصوتِ في أيامٍ مشؤوماتٍ عليهم، لنذيقهم عذابَ الذلِّ في الدنيا، ولعذابُ الآخرةِ أشدُّ خزيًا، وهم لا يُنصَرون؛ ففي هذا بيانُ عقوبةِ عادٍ في الدارين؛ فاحذر ما يوصل إلى عذابِ الخزي في الدنيا والآخرة، واعلم أنّ القوّةَ لا تنصر من عذاب الله، فاتّق الله ولا تغترّ بقوّة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من عذابِ الخزي، وإدراكُ أنّ القوّةَ لا تنصر من عذابِ الله."},"action":{"text":"تأمّل عقوبةَ عادٍ في الدارين: فأرسل الله على عادٍ ريحًا صرصرًا، شديدةَ البردِ عاصفةً ذاتَ صوتٍ مزعج، في أيامٍ نحساتٍ مشؤوماتٍ عليهم، لنذيقهم عذابَ الخزيِ والذلِّ في الحياةِ الدنيا؛ ولعذابُ الآخرةِ أشدُّ خزيًا وأعظم؛ وهم لا يُنصَرون ولا يُدفَع عنهم العذاب «فأرسلنا عليهم ريحا صرصرا في أيام نحسات لنذيقهم عذاب الخزي في الحياة الدنيا ولعذاب الآخرة أخزى وهم لا ينصرون»؛ ففي هذا بيانُ عقوبةِ عادٍ الأقوياءِ في الدنيا والآخرة؛ فأهلكهم الله بريحٍ رغمَ قوّتهم؛ سخّرها عليهم سبعَ ليالٍ وثمانيةَ أيامٍ حسومًا؛ فاحذر ما يوصل إلى عذابِ الخزيِ في الدنيا والآخرةِ من الكِبرِ والجحودِ والمعاصي؛ واعلم أنّ القوّةَ والعددَ لا ينصران من عذابِ الله؛ فعادٌ الأقوياءُ لم تنصرهم قوّتهم؛ فلا تغترّ بقوّةٍ ولا عددٍ ولا مال؛ فإنها لا تدفع عذابَ الله؛ فاتّق الله، واجتنب أسبابَ عذابه؛ فمن اتّقى الله نجّاه، ومن اغترّ بقوّته أهلكه؛ فالعزّةُ في طاعةِ الله، والذلُّ والخزيُ في معصيته؛ فاطلب النجاةَ بالتقوى، لا بالقوّةِ والعدد."}},{"n":17,"reflection":{"text":"«وأما ثمود فهديناهم فاستحبوا العمى على الهدى فأخذتهم صاعقة العذاب الهون بما كانوا يكسبون»، وأما ثمودُ فبيّنّا لهم الحقَّ (هدايةَ الدلالة) فاختاروا الضلالةَ على الهدى، فأخذتهم صاعقةُ العذابِ المذلّ بما كسبوا؛ ففي هذا ذمُّ إيثارِ الضلالةِ على الهدى؛ فاحذر أن تؤثر العمى على الهدى بعد بيانِ الحق، فاختر الهدى واتّبعه، فمن آثر الضلالةَ على الهدى استحقّ العذاب، فاختر الهدى لتنجو.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اختيارُ الهدى واتّباعُه، والحذرُ من إيثارِ العمى عليه."},"action":{"text":"تأمّل عاقبةَ ثمودَ وسببها: وأما ثمودُ قومُ صالحٍ فهديناهم هدايةَ الدلالةِ والبيان، فبيّنّا لهم الحقَّ وأوضحناه؛ فاستحبّوا واختاروا العمى والضلالةَ على الهدى والبصيرة؛ فأخذتهم صاعقةُ العذابِ المذلِّ المهينِ بسببِ ما كانوا يكسبون من الكفرِ والمعاصي «وأما ثمود فهديناهم فاستحبوا العمى على الهدى فأخذتهم صاعقة العذاب الهون بما كانوا يكسبون»؛ ففي هذا ذمُّ إيثارِ الضلالةِ على الهدى بعد وضوحه؛ فثمودُ بُيّن لهم الحقُّ فاختاروا الضلالةَ عليه؛ فاحذر أن تؤثر العمى والضلالةَ على الهدى والبصيرةِ بعد بيانِ الحق؛ فمن أعظمِ الجرمِ أن يعرف العبدُ الحقَّ ثم يختار الباطلَ عليه؛ فاختر الهدى واتّبعه إذا تبيّن لك؛ ولا تختر العمى والضلالةَ بعد وضوحِ الحق؛ فمن آثر الضلالةَ على الهدى استحقّ العذابَ المهين؛ فبادر باتّباعِ الهدى إذا عرفته؛ ولا تعاند الحقَّ وتؤثر عليه الباطل؛ فمن اتّبع الهدى نجا، ومن آثر العمى عليه هلك؛ فاجعل اختيارك الهدى والبصيرةَ دائمًا؛ فالهدى نجاة، والعمى هلاك."}},{"n":18,"reflection":{"text":"«ونجينا الذين آمنوا وكانوا يتقون»، ونجّينا الذين آمنوا وكانوا يتّقون من العذابِ الذي حلّ بالمكذّبين؛ ففي هذا نجاةُ المؤمنين المتّقين؛ فاعلم أنّ الإيمانَ والتقوى سببُ النجاةِ من العذاب، فآمن واتّق لتكون من الناجين، فالمؤمنون المتّقون ينجّيهم الله من العذابِ النازلِ بالمكذّبين.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإيمانُ والتقوى سبيلَ النجاةِ من العذاب."},"action":{"text":"تأمّل نجاةَ المؤمنين مقابلَ هلاكِ المكذّبين: ونجّينا الذين آمنوا من قومِ عادٍ وثمودَ وغيرهم، وكانوا يتّقون الله بامتثالِ أمره واجتنابِ نهيه، من العذابِ الذي حلّ بالمكذّبين المعاندين «ونجينا الذين آمنوا وكانوا يتقون»؛ ففي هذا بيانُ نجاةِ المؤمنين المتّقين من العذابِ النازلِ بالمكذّبين؛ فالله ينجّي أولياءه المؤمنين المتّقين حين يهلك المكذّبين؛ فاعلم أنّ الإيمانَ والتقوى سببُ النجاةِ من العذابِ في الدنيا والآخرة؛ فآمن بالله واتّق بامتثالِ أوامره واجتنابِ نواهيه، لتكون من الناجين؛ فالمؤمنون المتّقون ينجّيهم الله من العذابِ النازلِ بالمكذّبين؛ ثم ننجّي رسلنا والذين آمنوا كذلك حقًّا علينا نُنجِ المؤمنين؛ فاجعل الإيمانَ والتقوى حصنك من العذاب؛ فمن آمن واتّقى نجا، ومن كفر وعصى هلك؛ فالزم الإيمانَ والتقوى؛ فبهما النجاةُ في الدارين؛ فاجعل التقوى زادك، والإيمانَ عصمتك؛ فالله وليُّ المؤمنين المتّقين، ينجّيهم ويحفظهم؛ فكن منهم تنجُ من العذاب."}}]},{"title":"شهادةُ الجوارحِ يومَ القيامة، وسوءُ الظنِّ بالله المُردي","range":[19,24],"theme":"حشرُ أعداءِ الله إلى النارِ وشهادةُ سمعهم وأبصارهم وجلودهم عليهم بأعمالهم، وأنّ الله أنطق كلَّ شيء، وأنهم ما استتروا من جوارحهم بل ظنّوا أنّ الله لا يعلم كثيرًا مما يعملون، وأنّ سوءَ ظنّهم بربهم أرداهم فأصبحوا من الخاسرين، وأنه لا صبرَ لهم في النارِ ولا استعتاب","verses":[{"n":19,"reflection":{"text":"«ويوم يحشر أعداء الله إلى النار فهم يوزعون»، واذكر يومَ يُجمَع أعداءُ الله إلى النار، فيُساقون ويُحبَس أوّلهم على آخرهم؛ ففي هذا مشهدُ حشرِ أعداءِ الله إلى النار؛ فاحذر أن تكون من أعداءِ الله الذين يُحشَرون إلى النار، فكن من أولياءِ الله المؤمنين، فأعداءُ الله مصيرهم النار، فاطلب ولايةَ الله بالإيمانِ والطاعة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"طلبُ ولايةِ الله بالإيمانِ والطاعة، والحذرُ من عداوته."},"action":{"text":"تأمّل مشهدَ حشرِ أعداءِ الله: واذكر يومَ يُحشَر ويُجمَع أعداءُ الله، الكفّارُ والمكذّبون، إلى النار، فهم يُوزَعون، أي يُساقون ويُحبَس أوّلهم على آخرهم ليجتمعوا ثم يُدفَعوا إليها جميعًا «ويوم يحشر أعداء الله إلى النار فهم يوزعون»؛ ففي هذا مشهدُ حشرِ أعداءِ الله إلى النارِ سوقًا وجمعًا؛ فاحذر أن تكون من أعداءِ الله الذين يُحشَرون إلى النار؛ وعداوةُ الله تكون بالكفرِ والشركِ والمعاصيِ ومحادّةِ الله ورسوله؛ فكن من أولياءِ الله المؤمنين المتّقين؛ ألا إنّ أولياءَ الله لا خوفٌ عليهم ولا هم يحزنون؛ فأعداءُ الله مصيرهم النار، وأولياؤه مصيرهم الجنّة؛ فاطلب ولايةَ الله بالإيمانِ والتقوى والطاعةِ ومحبّةِ ما يحبّ وبغضِ ما يبغض؛ الله وليُّ الذين آمنوا؛ فمن آمن واتّقى كان من أولياءِ الله، ومن كفر وعصى كان من أعدائه؛ فاختر لنفسك أن تكون من أولياءِ الله لا من أعدائه؛ فاعمل عملَ الأولياء من الإيمانِ والتقوى والطاعة؛ فتنجو من حشرِ الأعداءِ إلى النار."}},{"n":20,"reflection":{"text":"«حتى إذا ما جاءوها شهد عليهم سمعهم وأبصارهم وجلودهم بما كانوا يعملون»: حتى إذا جاؤوا النارَ شهد عليهم سمعهم وأبصارهم وجلودهم بما كانوا يعملون؛ ففي هذا شهادةُ الجوارحِ على أصحابها؛ فاحذر المعاصيَ فإنّ جوارحك ستشهد عليك يومَ القيامة، فاستعمل جوارحك في طاعةِ الله لتشهد لك، فمن عصى بجوارحه شهدت عليه، ومن أطاع بها شهدت له.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"استعمالُ الجوارحِ في الطاعة، فإنها تشهد على أصحابها."},"action":{"text":"تأمّل شهادةَ الجوارحِ يومَ القيامة: حتى إذا جاء أعداءُ الله النارَ، شهد عليهم سمعهم وأبصارهم وجلودهم، التي عصوا الله بها، بما كانوا يعملون في الدنيا من الكفرِ والمعاصي «حتى إذا ما جاءوها شهد عليهم سمعهم وأبصارهم وجلودهم بما كانوا يعملون»؛ ففي هذا شهادةُ الجوارحِ على أصحابها يومَ القيامة؛ فينطق الله الجوارحَ فتشهد على صاحبها بما عمل؛ اليومَ نختم على أفواههم وتكلّمنا أيديهم وتشهد أرجلهم بما كانوا يكسبون؛ فاحذر المعاصيَ فإنّ جوارحك، سمعك وبصرك وجلدك ويدك ورجلك، ستشهد عليك يومَ القيامة بما عملت؛ فراقب الله في استعمالِ جوارحك؛ واستعملها في طاعةِ الله لا في معصيته؛ فاجعل سمعك في سماعِ القرآنِ والذكرِ والحق، وبصرك في النظرِ فيما ينفع، ولسانك في الذكرِ والخير، وجوارحك في الطاعة؛ فمن أطاع الله بجوارحه شهدت له، ومن عصاه بها شهدت عليه؛ فاستعمل نعمَ الجوارحِ في مرضاةِ الله؛ فإنك مسؤولٌ عنها؛ إنّ السمعَ والبصرَ والفؤادَ كلُّ أولئك كان عنه مسؤولًا؛ فاحفظ جوارحك عن الحرام؛ فإنها شاهدةٌ عليك أو لك."}},{"n":21,"reflection":{"text":"«وقالوا لجلودهم لم شهدتم علينا قالوا أنطقنا الله الذي أنطق كل شيء وهو خلقكم أول مرة وإليه ترجعون»، وقالوا لجلودهم: لم شهدتم علينا؟ قالوا: أنطقنا الله الذي أنطق كلَّ شيء، وهو خلقكم أوّلَ مرّة وإليه تُرجَعون؛ ففي هذا قدرةُ الله على إنطاقِ الجوارحِ وتقريرُ البعث؛ فاعلم أنّ الله ينطق جوارحك يومَ القيامة، فراقبه في السرِّ والعلن، فمن خلقك أوّلَ مرّة يعيدك ويحاسبك، فاستعدّ للرجوعِ إليه.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"مراقبةُ الله في السرِّ والعلن، والاستعدادُ للرجوعِ إليه."},"action":{"text":"تأمّل حوارَ أعداءِ الله مع جلودهم: وقالوا لجلودهم لائمين: لم شهدتم علينا بما كنّا نعمل؟ قالت الجلود: أنطقنا الله الذي أنطق كلَّ شيء، فلا نملك إلا الشهادةَ بالحق؛ وهو خلقكم أوّلَ مرّةٍ من العدم، وإليه تُرجَعون للحسابِ والجزاء «وقالوا لجلودهم لم شهدتم علينا قالوا أنطقنا الله الذي أنطق كل شيء وهو خلقكم أول مرة وإليه ترجعون»؛ ففي هذا بيانُ قدرةِ الله على إنطاقِ الجوارحِ وكلِّ شيء، وتقريرُ البعثِ والرجوعِ إليه؛ فالله الذي أنطق كلَّ شيءٍ قادرٌ على إنطاقِ جوارحك لتشهد عليك؛ فاعلم أنّ الله ينطق جوارحك يومَ القيامةِ فتشهد عليك بما عملت؛ فراقب الله في السرِّ والعلن؛ فلا يخفى عليه شيءٌ من عملك، وجوارحك ستشهد به؛ واعلم أنّ من خلقك أوّلَ مرّةٍ من العدمِ قادرٌ على أن يعيدك ويبعثك ويحاسبك؛ كما بدأكم تعودون؛ فاستعدّ للرجوعِ إلى الله بالإيمانِ والعملِ الصالح؛ فإليه مرجعك ومصيرك؛ فمن راقب الله في الدنيا وأطاعه شهدت له جوارحه، ومن عصاه شهدت عليه؛ فاستعدّ للقاءِ الله والرجوعِ إليه؛ فراقبه، وأطعه، وأحسن عملك."}},{"n":22,"reflection":{"text":"«وما كنتم تستترون أن يشهد عليكم سمعكم ولا أبصاركم ولا جلودكم ولكن ظننتم أن الله لا يعلم كثيرا مما تعملون»، وما كنتم تستترون عند المعصيةِ خشيةَ أن تشهد عليكم جوارحكم، ولكن ظننتم أنّ الله لا يعلم كثيرًا مما تعملون؛ ففي هذا ذمُّ سوءِ الظنِّ بعلمِ الله؛ فاحذر أن تظنّ أنّ الله لا يعلم بعضَ عملك، فالله يعلم كلَّ شيء، فراقبه في كلِّ حال، واعلم أنّ الله محيطٌ بعملك كلِّه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بإحاطةِ علمِ الله بكلِّ عمل، ومراقبتُه في كلِّ حال."},"action":{"text":"تأمّل بيانَ الله لسببِ جرأتهم على المعصية: وما كنتم تستترون وتختبئون عند فعلِ المعاصيِ خشيةَ أن تشهد عليكم جوارحكم، سمعكم وأبصاركم وجلودكم، فأنتم لم تتّقوها؛ ولكنّ الذي حملكم على المعاصي أنكم ظننتم أنّ الله لا يعلم كثيرًا مما تعملون «وما كنتم تستترون أن يشهد عليكم سمعكم ولا أبصاركم ولا جلودكم ولكن ظننتم أن الله لا يعلم كثيرا مما تعملون»؛ ففي هذا ذمُّ سوءِ الظنِّ بعلمِ الله، وأنه من أعظمِ أسبابِ الجرأةِ على المعصية؛ فظنّهم أنّ الله لا يعلم بعضَ أعمالهم حملهم على الجرأةِ عليها؛ فاحذر أن تظنّ أنّ الله لا يعلم شيئًا من عملك أو يغفل عنه؛ فالله يعلم كلَّ شيء، لا يخفى عليه شيءٌ في الأرضِ ولا في السماء؛ ألا يعلم من خلق وهو اللطيفُ الخبير؛ يعلم خائنةَ الأعينِ وما تخفي الصدور؛ فراقب الله في كلِّ حال، سرًّا وعلنًا؛ واعلم أنّ الله محيطٌ بعملك كلِّه، مطّلعٌ على أدقِّ خفاياك؛ فمن أيقن بإحاطةِ علمِ الله استحيا منه واجتنب المعاصي؛ ومن ظنّ أنّ الله يغفل عن بعضِ عمله تجرّأ على المعصية؛ فأحسن ظنّك بعلمِ الله وإحاطته؛ وراقبه في السرِّ كما تراقبه في العلن؛ فالله رقيبٌ عليك، عليمٌ بعملك."}},{"n":23,"reflection":{"text":"«وذلكم ظنكم الذي ظننتم بربكم أرداكم فأصبحتم من الخاسرين»، وذلك ظنّكم السيّئُ بربّكم (أنه لا يعلم عملكم) أهلككم، فأصبحتم من الخاسرين؛ ففي هذا بيانُ أنّ سوءَ الظنِّ بالله سببُ الهلاك؛ فأحسن ظنّك بالله في علمه وقدرته وحكمته، فسوءُ الظنِّ بالله يُردي ويُهلك، فاجعل ظنّك بالله حسنًا، فمن أساء الظنَّ بالله خسر.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"إحسانُ الظنِّ بالله، فسوءُ الظنِّ به سببُ الهلاكِ والخسران."},"action":{"text":"تأمّل بيانَ الله لعاقبةِ سوءِ الظنِّ به: وذلكم ظنّكم السيّئُ الذي ظننتموه بربّكم، من أنه لا يعلم كثيرًا من أعمالكم، أو أنه لا يبعثكم ولا يحاسبكم، هو الذي أرداكم وأهلككم، فأصبحتم بسببه من الخاسرين خسرانًا لا جبرَ له «وذلكم ظنكم الذي ظننتم بربكم أرداكم فأصبحتم من الخاسرين»؛ ففي هذا بيانُ أنّ سوءَ الظنِّ بالله من أعظمِ أسبابِ الهلاكِ والخسران؛ فظنّهم السيّئُ بالله أهلكهم؛ فأحسن ظنّك بالله في علمه المحيط، وقدرته التامّة، وحكمته البالغة، ورحمته الواسعة، وعدله؛ واحذر سوءَ الظنِّ بالله؛ فمن ظنّ أنّ الله لا يعلم عمله، أو لا يبعثه، أو لا ينصر دينه، أو لا يجازي المحسن والمسيء، فقد أساء الظنَّ بالله؛ الظانّين بالله ظنَّ السوءِ عليهم دائرةُ السوء؛ فسوءُ الظنِّ بالله يُردي ويُهلك؛ فاجعل ظنّك بالله حسنًا؛ أنا عند ظنِّ عبدي بي؛ فأحسن الظنَّ بالله في علمه وقدرته وحكمته ورحمته وعدله ووعده؛ فمن أحسن الظنَّ بالله نجا، ومن أساءه هلك وخسر؛ فاحذر أن تكون من الخاسرين بسوءِ ظنّك بالله؛ بل أحسن ظنّك به؛ فبإحسانِ الظنِّ بالله تُنال النجاةُ والفلاح."}},{"n":24,"reflection":{"text":"«فإن يصبروا فالنار مثوى لهم وإن يستعتبوا فما هم من المعتبين»: فإن يصبروا على العذابِ فالنارُ مقامهم، وإن يطلبوا العتبى والرضا فما هم ممّن يُعتَبون ويُرضَون؛ ففي هذا بيانُ أنه لا مفرَّ لأهلِ النارِ من العذاب؛ فاحذر أن تصير إلى حالٍ لا ينفع فيه صبرٌ ولا استعتاب، فاعمل الآن لتنجو، فأهلُ النارِ لا يُقبَل منهم صبرٌ ولا اعتذار، فبادر بالطاعةِ قبل ذلك.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"المبادرةُ بالعمل، فأهلُ النارِ لا ينفعهم صبرٌ ولا استعتاب."},"action":{"text":"تأمّل حالَ أهلِ النارِ التي لا مخرجَ منها: فإن يصبر أعداءُ الله على العذابِ فالنارُ مثوًى ومقامٌ دائمٌ لهم، لا ينفعهم صبرهم؛ وإن يستعتبوا ويطلبوا العتبى والرضا والرجوعَ إلى الدنيا ليعملوا صالحًا، فما هم ممّن يُعتَبون ويُجابون إلى ذلك «فإن يصبروا فالنار مثوى لهم وإن يستعتبوا فما هم من المعتبين»؛ ففي هذا بيانُ أنه لا مفرَّ لأهلِ النارِ من العذاب؛ فلا ينفعهم صبرٌ عليه، ولا استعتابٌ واعتذارٌ يُقبَل؛ فاحذر أن تصير إلى حالٍ لا ينفع فيه صبرٌ ولا استعتابٌ ولا اعتذار؛ سواءٌ علينا أجزعنا أم صبرنا ما لنا من محيص؛ فاعمل الآن في زمنِ المهلةِ لتنجو من ذلك المصير؛ فأهلُ النارِ لا يُقبَل منهم صبرٌ ولا اعتذارٌ ولا استعتاب؛ ولا يُؤذَن لهم فيعتذرون؛ ربّنا أخرجنا منها فإن عدنا فإنا ظالمون قال اخسؤوا فيها ولا تكلّمون؛ فبادر بالإيمانِ والطاعةِ والتوبةِ قبل أن تصير إلى حالٍ لا ينفع فيه شيء؛ فالسعيدُ من عمل في الدنيا فنجا، والشقيُّ من فرّط فصار إلى عذابٍ لا مخرجَ منه؛ فاغتنم مهلتك بالعملِ الصالحِ والتوبة."}}]},{"title":"قرناءُ السوءِ المزيّنون، وحربُ الكافرين للقرآن، وعذابهم وندمُهم","range":[25,29],"theme":"تقييضُ قرناءِ سوءٍ للكافرين زيّنوا لهم أعمالهم فحقّ عليهم القولُ في أممٍ خلت، ومحاربةُ الكافرين للقرآنِ باللغوِ والتشويشِ ليغلبوا، ووعيدُهم بعذابٍ شديدٍ وجزائهم بأسوأِ أعمالهم، وأنّ جزاءَ أعداءِ الله النارُ دارَ الخلدِ جزاءَ جحودهم آياتِه، وندمُ الأتباعِ وطلبُهم الانتقامَ من مُضِلّيهم من الجنِّ والإنس","verses":[{"n":25,"reflection":{"text":"«وقيضنا لهم قرناء فزينوا لهم ما بين أيديهم وما خلفهم وحق عليهم القول في أمم قد خلت من قبلهم من الجن والإنس إنهم كانوا خاسرين»، وسبّبنا لهم قرناءَ سوءٍ زيّنوا لهم أعمالهم القبيحةَ حاضرَها ومستقبلها، وحقّ عليهم العذابُ مع أممٍ خلت من الجنِّ والإنس، إنهم كانوا خاسرين؛ ففي هذا خطرُ قرناءِ السوءِ الذين يزيّنون الباطل؛ فاحذر قرينَ السوءِ الذي يزيّن لك الباطل، واختر القرينَ الصالح، فقرينُ السوءِ يورد الهلاك.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من قرينِ السوء، واختيارُ القرينِ الصالح."},"action":{"text":"تأمّل خطرَ قرناءِ السوء: وقيّضنا وسبّبنا للكافرين المعرضين قرناءَ سوءٍ من الشياطينِ وشرارِ الإنس، لازموهم فزيّنوا لهم ما بين أيديهم من أمرِ الدنيا وشهواتها، وما خلفهم من إنكارِ الآخرةِ والبعث؛ وحقّ عليهم العذابُ والقولُ الذي حقّ على أممٍ قد خلت من قبلهم من الجنِّ والإنس؛ إنهم كانوا خاسرين لأنفسهم وأهليهم «وقيضنا لهم قرناء فزينوا لهم ما بين أيديهم وما خلفهم وحق عليهم القول في أمم قد خلت من قبلهم من الجن والإنس إنهم كانوا خاسرين»؛ ففي هذا بيانُ خطرِ قرناءِ السوءِ الذين يزيّنون الباطلَ والمعاصي؛ فقرينُ السوءِ يزيّن لصاحبه الشرَّ ويصدّه عن الخير؛ فاحذر قرينَ السوءِ الذي يزيّن لك الباطلَ والمعاصيَ وينسيك الآخرة؛ فالقرينُ السوءُ يجرّ صاحبه إلى الهلاك؛ ومن يعش عن ذكرِ الرحمنِ نقيّض له شيطانًا فهو له قرين؛ فاختر القرينَ الصالحَ الذي يعينك على الخيرِ ويذكّرك بالله؛ فالمرءُ على دينِ خليله؛ فمثلُ الجليسِ الصالحِ كحاملِ المسك؛ وجليسِ السوءِ كنافخِ الكير؛ فاحرص على صحبةِ الأخيارِ الصالحين؛ واحذر صحبةَ الأشرارِ المزيّنين للباطل؛ فقرينُ الخيرِ يدلّك على الجنّة، وقرينُ السوءِ يوردك النار؛ فاختر قرينك بعناية؛ فبالقرينِ الصالحِ تسعد، وبقرينِ السوءِ تشقى."}},{"n":26,"reflection":{"text":"«وقال الذين كفروا لا تسمعوا لهذا القرآن والغوا فيه لعلكم تغلبون»، وقال الكافرون: لا تسمعوا لهذا القرآن، وأكثروا اللغطَ والتشويشَ عند تلاوته لعلّكم تغلبون؛ ففي هذا محاربةُ الكافرين للقرآنِ بالتشويش؛ فاعلم أنّ أعداءَ الحقِّ يحاربونه بالتشويشِ والصدِّ عن سماعه، فاحرص أنت على سماعِ القرآنِ والإنصاتِ له، ولا تكن ممّن يصدّ عنه أو يشوّش عليه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحرصُ على سماعِ القرآنِ والإنصاتِ له، ونصرتُه."},"action":{"text":"تأمّل حربَ الكافرين للقرآن: وقال الذين كفروا يوصي بعضهم بعضًا: لا تسمعوا لهذا القرآنِ ولا تنصتوا له، والغوا فيه، أي أكثروا اللغطَ والصياحَ والتشويشَ عند تلاوته، لعلّكم تغلبون محمدًا وتصدّون الناسَ عن سماعه «وقال الذين كفروا لا تسمعوا لهذا القرآن والغوا فيه لعلكم تغلبون»؛ ففي هذا بيانُ محاربةِ الكافرين للقرآنِ بالتشويشِ والصدِّ عن سماعه؛ فلمّا عجزوا عن معارضته لجؤوا إلى التشويشِ والصدّ؛ وهذا يدلّ على تأثيرِ القرآنِ وقوّتِه، حتى خافوا أن يسمعه الناسُ فيؤمنوا؛ فاعلم أنّ أعداءَ الحقِّ يحاربون القرآنَ بالتشويشِ والصدِّ عن سماعه والإعراضِ عنه؛ فاحرص أنت على سماعِ القرآنِ والإنصاتِ له بقلبٍ حاضر؛ وإذا قُرِئ القرآنُ فاستمعوا له وأنصتوا لعلّكم تُرحَمون؛ ولا تكن ممّن يصدّ عن القرآنِ أو يشوّش عليه أو يعرض عنه؛ بل انصر القرآنَ بسماعه وتدبّره والعملِ به ونشره؛ فمن أنصت للقرآنِ وتدبّره اهتدى به، ومن أعرض عنه وشوّش عليه حُرِم خيره؛ فاجعل للقرآنِ في قلبك مكانةً، ولسماعه في وقتك نصيبًا؛ فبالإنصاتِ للقرآنِ تُنال الرحمةُ والهداية."}},{"n":27,"reflection":{"text":"«فلنذيقن الذين كفروا عذابا شديدا ولنجزينهم أسوأ الذي كانوا يعملون»: فلنذيقنّ الكافرين عذابًا شديدًا، ولنجزينّهم بأسوأِ أعمالهم؛ ففي هذا وعيدُ الكافرين بالعذابِ الشديد؛ فاحذر الكفرَ والصدَّ عن الحقِّ الذي عاقبتُه العذابُ الشديد، فاعمل لتنجو منه، فالكافرون سيُجزَون بأسوأِ أعمالهم، فبادر بالإيمانِ والعملِ الصالح.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الكفرِ الموجبِ للعذابِ الشديد، والمبادرةُ بالإيمان."},"action":{"text":"تأمّل وعيدَ الله للكافرين المحاربين للقرآن: فلنذيقنّ الذين كفروا وصدّوا عن القرآنِ عذابًا شديدًا أليمًا، ولنجزينّهم بأسوأِ الذي كانوا يعملون من الكفرِ والصدِّ والمعاصي «فلنذيقن الذين كفروا عذابا شديدا ولنجزينهم أسوأ الذي كانوا يعملون»؛ ففي هذا وعيدُ الكافرين بالعذابِ الشديدِ والجزاءِ بأسوأِ أعمالهم؛ فاحذر الكفرَ والصدَّ عن الحقِّ والقرآنِ الذي عاقبتُه العذابُ الشديد؛ فمن كفر بالله وصدّ عن سبيله استحقّ العذابَ الشديد؛ فاعمل لتنجو من هذا العذاب بالإيمانِ والتوحيدِ والطاعة؛ فالكافرون سيُجزَون بأسوأِ أعمالهم؛ فبادر بالإيمانِ والعملِ الصالحِ والتوبةِ قبل نزولِ العذاب؛ ولا تكن ممّن يحارب الحقَّ أو يصدّ عنه أو يعرض عن القرآن؛ بل كن من المؤمنين المتّبعين للحق؛ فمن آمن وعمل صالحًا نجا من العذاب، ومن كفر وصدّ عُذّب عذابًا شديدًا؛ فاختر لنفسك سبيلَ الناجين؛ فبادر بالإيمانِ والطاعةِ قبل فواتِ الأوان."}},{"n":28,"reflection":{"text":"«ذلك جزاء أعداء الله النار لهم فيها دار الخلد جزاء بما كانوا بآياتنا يجحدون»: ذلك العذابُ جزاءُ أعداءِ الله، النار، لهم فيها دارُ الخلود، جزاءً بجحودهم آياتِنا؛ ففي هذا بيانُ خلودِ أعداءِ الله في النارِ جزاءَ الجحود؛ فاحذر جحودَ آياتِ الله الذي عاقبتُه الخلودُ في النار، فآمن بآياتِ الله وأقرّ بها، فالجحودُ يوجب الخلودَ في النار، فصدّق بآياتِ الله لتنجو.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإيمانُ بآياتِ الله، والحذرُ من جحودها الموجبِ للخلودِ في النار."},"action":{"text":"تأمّل جزاءَ أعداءِ الله: ذلك العذابُ الشديدُ جزاءُ أعداءِ الله، وهو النار؛ لهم فيها دارُ الخلودِ والإقامةِ الدائمةِ التي لا يخرجون منها؛ جزاءً وعقوبةً بسببِ ما كانوا بآياتِ الله يجحدون وينكرون بعد وضوحها «ذلك جزاء أعداء الله النار لهم فيها دار الخلد جزاء بما كانوا بآياتنا يجحدون»؛ ففي هذا بيانُ خلودِ أعداءِ الله في النارِ جزاءَ جحودهم لآياتِ الله؛ فسببُ خلودهم في النارِ جحودهم لآياتِ الله وإنكارها؛ فاحذر جحودَ آياتِ الله، القرآنيةِ والكونيةِ، وإنكارها بعد وضوحها؛ فإنّ الجحودَ يوجب الخلودَ في النار؛ فآمن بآياتِ الله كلِّها، وأقرّ بها، وصدّق بدلالتها؛ فالإيمانُ بآياتِ الله سبيلُ النجاة، وجحودها سبيلُ الخلودِ في النار؛ فلا تكن من الجاحدين المنكرين لآياتِ الله؛ بل كن من المؤمنين المصدّقين المقرّين بها؛ فمن آمن بآياتِ الله نجا، ومن جحدها خلد في النار؛ فصدّق بآياتِ الله، وأقرّ بها، وانتفع بها؛ فبالإيمانِ بآياتِ الله تُنال النجاة، وبجحودها يقع الخلودُ في النار؛ فاجعل قلبك مؤمنًا بآياتِ الله، مقرًّا بها."}},{"n":29,"reflection":{"text":"«وقال الذين كفروا ربنا أرنا اللذين أضلانا من الجن والإنس نجعلهما تحت أقدامنا ليكونا من الأسفلين»، وقال الكافرون في النار: ربّنا أرِنا اللذين أضلّانا من الجنِّ والإنس نجعلهما تحت أقدامنا ليكونا من الأسفلين؛ ففي هذا ندمُ الأتباعِ وطلبهم الانتقامَ من مُضِلّيهم؛ فاحذر أن تتّبع من يضلّك فتندم، ولا تكن مُضِلًّا لغيرك فتُطلَب، فاتّبع الحقَّ ولا تقلّد المضلّين، فالتبعيةُ في الضلالِ ندامة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اتّباعُ الحقِّ وتركُ تقليدِ المضلّين، فالتبعيةُ في الضلالِ ندامة."},"action":{"text":"تأمّل ندمَ الأتباعِ في النار: وقال الذين كفروا وهم في النارِ نادمين: ربّنا أرِنا اللذين أضلّانا من الجنِّ والإنس، شيطانَ الجنِّ الذي دعا إلى الكفر، وشيطانَ الإنسِ الذي سنّ الضلالَ ودعا إليه، نجعلهما تحت أقدامنا انتقامًا منهما، ليكونا من الأسفلين الأذلّين في النار «وقال الذين كفروا ربنا أرنا اللذين أضلانا من الجن والإنس نجعلهما تحت أقدامنا ليكونا من الأسفلين»؛ ففي هذا ندمُ الأتباعِ في النار، وطلبهم الانتقامَ من مُضِلّيهم من شياطينِ الجنِّ والإنس؛ فتبرّؤوا من مُضِلّيهم وتمنّوا الانتقامَ منهم حين لا ينفع؛ فاحذر أن تتّبع من يضلّك من شياطينِ الجنِّ والإنس فتندم يومَ القيامة؛ ولا تكن أنت مُضِلًّا لغيرك فتُطلَب ويُدعى عليك؛ فاتّبع الحقَّ وحده، ولا تقلّد المضلّين على الباطل؛ فالتبعيةُ في الضلالِ ندامةٌ وحسرةٌ يومَ القيامة؛ فينقلب الأخلّاءُ يومئذٍ بعضهم لبعضٍ عدوًّا إلا المتّقين؛ فلا تجعل ولاءك ومحبّتك لمن يضلّك؛ بل والِ أهلَ الحقِّ والهدى؛ فمن اتّبع مُضِلًّا ندم عليه، ومن اتّبع الحقَّ نجا؛ فاتّبع الحقَّ، وتبرّأ من دعاةِ الضلالِ في الدنيا، قبل أن تتبرّأ منهم في الآخرةِ حين لا ينفع."}}]},{"title":"بشرى المستقيمين وتنزّلُ الملائكة، وفضلُ الدعوةِ إلى الله ودفعِ السيّئةِ بالحسنى","range":[30,36],"theme":"بشرى الذين قالوا ربنا الله ثم استقاموا بتنزّلِ الملائكةِ عليهم بألا يخافوا ولا يحزنوا والبشارةِ بالجنّة، وأنّ الملائكةَ أولياؤهم في الدارين ولهم ما تشتهي أنفسهم نُزُلًا من غفورٍ رحيم، وفضلُ من دعا إلى الله وعمل صالحًا واعتزَّ بإسلامه، والوصيّةُ بدفعِ السيّئةِ بالتي هي أحسن فيصير العدوُّ كأنه وليٌّ حميم وأنها لا يُوفَّق لها إلا الصابرون، والأمرُ بالاستعاذةِ عند نزغِ الشيطان","verses":[{"n":30,"reflection":{"text":"«إن الذين قالوا ربنا الله ثم استقاموا تتنزل عليهم الملائكة ألا تخافوا ولا تحزنوا وأبشروا بالجنة التي كنتم توعدون»: إنّ الذين قالوا ربّنا الله ثم استقاموا على التوحيدِ والطاعة، تتنزّل عليهم الملائكةُ عند الموت: ألا تخافوا ولا تحزنوا وأبشروا بالجنّة؛ ففي هذا بشارةُ المستقيمين وثمرةُ الاستقامة؛ فقل ربّي الله واستقم، لتنال بشرى الملائكةِ والأمنَ والجنّة، فالاستقامةُ سبيلُ الطمأنينةِ والبشرى، فاثبت على التوحيدِ والطاعة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاستقامةُ على التوحيدِ والطاعة، رجاءَ بشرى الملائكةِ والجنّة."},"action":{"text":"تأمّل هذه الآيةَ العظيمةَ في فضلِ الاستقامة: إنّ الذين قالوا ربّنا الله وحده لا شريكَ له، ثم استقاموا على التوحيدِ والطاعةِ والدينِ القويم، تتنزّل عليهم الملائكةُ عند الموتِ وفي القبرِ ويومَ البعثِ مبشّرين: ألا تخافوا مما تقدمون عليه، ولا تحزنوا على ما خلّفتم من دنيا وأهل، وأبشروا بالجنّةِ التي كنتم توعدون في الدنيا «إن الذين قالوا ربنا الله ثم استقاموا تتنزل عليهم الملائكة ألا تخافوا ولا تحزنوا وأبشروا بالجنة التي كنتم توعدون»؛ ففي هذا بشارةُ المستقيمين، وثمرةُ الاستقامةِ العظيمة؛ فمن قال ربّي الله واستقام نال هذه البشرى؛ فقل ربّي الله، واستقم على ذلك بالتوحيدِ والطاعةِ والثباتِ على الدين؛ قل آمنت بالله ثم استقم؛ فالاستقامةُ لزومُ الصراطِ المستقيمِ في الاعتقادِ والقولِ والعمل، والثباتُ عليه حتى الممات؛ فاثبت على التوحيدِ والطاعة؛ لتنال بشرى الملائكةِ بالأمنِ من الخوف، وذهابِ الحزن، والبشارةِ بالجنّة؛ فالاستقامةُ سبيلُ الطمأنينةِ في الدنيا، والبشرى عند الموت، والفوزِ في الآخرة؛ فاسأل الله الثباتَ والاستقامة؛ واجتهد في لزومِ الصراطِ المستقيم؛ فمن استقام بشّرته الملائكةُ وفاز بالجنّة."}},{"n":31,"reflection":{"text":"«نحن أولياؤكم في الحياة الدنيا وفي الآخرة ولكم فيها ما تشتهي أنفسكم ولكم فيها ما تدعون»: تقول الملائكة: نحن أنصاركم في الدنيا والآخرة، ولكم في الجنّةِ ما تشتهي أنفسكم وما تطلبون؛ ففي هذا ولايةُ الملائكةِ للمستقيمين وسعةُ نعيمِ الجنّة؛ فاطلب ولايةَ الله وملائكتِه بالاستقامة، فالمستقيمون لهم في الجنّةِ ما يشتهون، فاعمل عملَ المستقيمين لتنال هذه الولايةَ والنعيم.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"طلبُ ولايةِ الله وملائكتِه بالاستقامة، رجاءَ نعيمِ الجنّة."},"action":{"text":"تأمّل تمامَ بشارةِ الملائكةِ للمستقيمين: تقول الملائكةُ لهم: نحن أولياؤكم وأنصاركم وأحبّاؤكم في الحياةِ الدنيا نسدّدكم ونحفظكم، وفي الآخرةِ نؤنسكم ونشفع لكم؛ ولكم في الجنّةِ ما تشتهي أنفسكم من النعيم، ولكم فيها ما تطلبون وتدّعون «نحن أولياؤكم في الحياة الدنيا وفي الآخرة ولكم فيها ما تشتهي أنفسكم ولكم فيها ما تدعون»؛ ففي هذا بيانُ ولايةِ الملائكةِ للمؤمنين المستقيمين في الدارين، وسعةِ نعيمِ الجنّة؛ فالملائكةُ أولياءُ المؤمنين المستقيمين، يحبّونهم ويستغفرون لهم ويثبّتونهم؛ فاطلب ولايةَ الله وملائكتِه بالاستقامةِ على التوحيدِ والطاعة؛ فالمستقيمون لهم في الجنّةِ كلُّ ما تشتهيه أنفسهم وتطلبه؛ لهم ما يشاؤون عند ربهم؛ وفيها ما تشتهيه الأنفسُ وتلذّ الأعين؛ فاعمل عملَ المستقيمين لتنال ولايةَ الله وملائكتِه، ونعيمَ الجنّةِ الذي لا حدَّ له؛ فمن استقام والاه الله وملائكتُه، وأعطاه في الجنّةِ ما يشتهي؛ فاجعل همّك الاستقامةَ لتفوز بهذه الولايةِ والكرامةِ والنعيم."}},{"n":32,"reflection":{"text":"«نزلا من غفور رحيم»: ذلك النعيمُ ضيافةٌ وعطاءٌ من غفورٍ رحيمٍ للذنوب؛ ففي هذا بيانُ أنّ النعيمَ من فضلِ الغفورِ الرحيم؛ فاعلم أنّ نعيمَ الجنّةِ من مغفرةِ الله ورحمته، فاطلب مغفرته ورحمته، فمن غفر الله له ورحمه أنزله جنّاتِ النعيم، فارجُ مغفرةَ الله ورحمته بالتوبةِ والاستقامة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"رجاءُ مغفرةِ الله ورحمته بالتوبةِ والاستقامة، فالنعيمُ من فضله."},"action":{"text":"تأمّل بيانَ مصدرِ نعيمِ الجنّة: ذلك النعيمُ الموصوفُ ضيافةٌ وإكرامٌ ونُزُلٌ من الله الغفورِ الذي يغفر الذنوب، الرحيمِ الذي وسعت رحمته كلَّ شيء «نزلا من غفور رحيم»؛ ففي هذا بيانُ أنّ نعيمَ الجنّةِ من فضلِ الله ومغفرته ورحمته؛ فأنزلهم الجنّةَ برحمته بعد أن غفر ذنوبهم؛ فاعلم أنّ نعيمَ الجنّةِ إنما يُنال بمغفرةِ الله ورحمته، لا بمجرّدِ العمل؛ لن يدخل أحدكم الجنّةَ بعمله، قالوا ولا أنت يا رسولَ الله؟ قال ولا أنا إلا أن يتغمّدني الله برحمة؛ فاطلب مغفرةَ الله ورحمته؛ فبهما تدخل الجنّة؛ فمن غفر الله له ذنوبه ورحمه أنزله جنّاتِ النعيمِ ضيافةً وإكرامًا؛ فأكثر من الاستغفارِ والتوبةِ رجاءَ المغفرة؛ واعمل صالحًا رجاءَ الرحمة؛ واجمع بين العملِ ورجاءِ فضلِ الله؛ فارجُ مغفرةَ الله ورحمته بالتوبةِ والاستقامةِ والعملِ الصالح؛ فمن رجا مغفرةَ الله ورحمته وعمل لهما نالهما ودخل جنّاتِ النعيم؛ فالنعيمُ من فضلِ الغفورِ الرحيم، فاطلبه بأسبابه."}},{"n":33,"reflection":{"text":"«ومن أحسن قولا ممن دعا إلى الله وعمل صالحا وقال إنني من المسلمين»، ومن أحسنُ قولًا ممّن دعا إلى الله وعمل صالحًا وقال إنني من المسلمين؟ ففي هذا بيانُ فضلِ الدعوةِ إلى الله مع العملِ الصالح؛ فادعُ إلى الله واعمل صالحًا واعتزَّ بإسلامك، فأحسنُ الناسِ قولًا الداعي إلى الله العاملُ بما يدعو إليه، فكن داعيًا عاملًا معتزًّا بدينك.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الدعوةُ إلى الله مع العملِ الصالحِ والاعتزازِ بالإسلام."},"action":{"text":"تأمّل فضلَ الدعوةِ إلى الله: ومن أحسنُ قولًا وأفضلُ كلامًا ممّن جمع ثلاثَ خصال: دعا الناسَ إلى الله وإلى توحيده وطاعته، وعمل صالحًا في نفسه، وقال معتزًّا بدينه: إنني من المسلمين المستسلمين لله؟ لا أحد أحسنُ قولًا منه «ومن أحسن قولا ممن دعا إلى الله وعمل صالحا وقال إنني من المسلمين»؛ ففي هذا بيانُ فضلِ الدعوةِ إلى الله مع العملِ الصالحِ والاعتزازِ بالإسلام؛ فأحسنُ الناسِ قولًا وأفضلهم من جمع هذه الخصالَ الثلاث؛ فادعُ إلى الله وإلى توحيده وطاعته بالحكمةِ والموعظةِ الحسنة؛ واعمل صالحًا فيما بينك وبين الله؛ وكن أوّلَ عاملٍ بما تدعو إليه؛ واعتزَّ بإسلامك ودينك، ولا تستحيِ منه؛ وقل: إنني من المسلمين؛ فالداعي إلى الله العاملُ بما يدعو إليه المعتزُّ بدينه أحسنُ الناسِ قولًا؛ فكن داعيًا إلى الله، عاملًا بما تدعو إليه، معتزًّا بإسلامك؛ فمن جمع بين الدعوةِ والعملِ والاعتزازِ بالدينِ فقد بلغ أعلى المقامات؛ فاجعل همّك الدعوةَ إلى الله، والعملَ الصالح، والاعتزازَ بالإسلام؛ فبذلك تكون من أحسنِ الناسِ قولًا."}},{"n":34,"reflection":{"text":"«ولا تستوي الحسنة ولا السيئة ادفع بالتي هي أحسن فإذا الذي بينك وبينه عداوة كأنه ولي حميم»، ولا تستوي الحسنةُ والسيّئة، ادفع الإساءةَ بالإحسان، فإذا الذي بينك وبينه عداوةٌ يصير كأنه صديقٌ حميم؛ ففي هذا وصيّةٌ بدفعِ السيّئةِ بالحسنى؛ فادفع إساءةَ الناسِ بالإحسانِ إليهم، فالإحسانُ يقلب العدوَّ صديقًا، فقابل الإساءةَ بالإحسان، فمن دفع السيّئةَ بالحسنةِ كسب القلوبَ وأطفأ العداوة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"دفعُ السيّئةِ بالحسنى، فالإحسانُ يقلب العدوَّ صديقًا."},"action":{"text":"تأمّل هذه الوصيّةَ العظيمةَ في الأخلاق: ولا تستوي الحسنةُ ولا السيّئة، بل بينهما بونٌ عظيم؛ ادفع إساءةَ من أساء إليك بالخصلةِ التي هي أحسن، بالعفوِ والإحسانِ والصبر، فإذا الذي بينك وبينه عداوةٌ وبغضاء يصير بإحسانك إليه كأنه وليٌّ حميمٌ قريبٌ محبّ «ولا تستوي الحسنة ولا السيئة ادفع بالتي هي أحسن فإذا الذي بينك وبينه عداوة كأنه ولي حميم»؛ ففي هذا وصيّةٌ عظيمةٌ بدفعِ السيّئةِ بالحسنى، ومقابلةِ الإساءةِ بالإحسان؛ فادفع إساءةَ الناسِ إليك بالإحسانِ إليهم، لا بالإساءةِ مثلهم؛ فالإحسانُ إلى المسيءِ يقلب العداوةَ محبّة، والبغضاءَ مودّة؛ ادفع بالتي هي أحسنُ السيّئة؛ فقابل الإساءةَ بالإحسان، والغضبَ بالحلم، والقطيعةَ بالصلة، والظلمَ بالعفو؛ فمن دفع السيّئةَ بالحسنةِ كسب القلوبَ وأطفأ نارَ العداوة؛ فتحوّل عدوّه إلى صديقٍ حميم؛ وليس الشديدُ بالصرعة، إنما الشديدُ الذي يملك نفسه عند الغضب؛ فاجعل خُلُقك دفعَ الإساءةِ بالإحسان؛ فبذلك تكسب المحبّةَ، وتطفئ العداوة، وتنال أجرَ الإحسان؛ فادفع بالتي هي أحسن، تكسب القلوبَ وتنل رضا الله."}},{"n":35,"reflection":{"text":"«وما يلقاها إلا الذين صبروا وما يلقاها إلا ذو حظ عظيم»، وما يُوفَّق لهذه الخصلةِ (دفعِ السيّئةِ بالحسنى) إلا الصابرون، وما يُوفَّق لها إلا صاحبُ الحظِّ العظيم؛ ففي هذا بيانُ أنّ دفعَ السيّئةِ بالحسنى يحتاج صبرًا وهو حظٌّ عظيم؛ فاصبر لتُوفَّق لدفعِ السيّئةِ بالحسنى، فهذه الخصلةُ حظٌّ عظيمٌ لا يناله إلا الصابرون، فتحلَّ بالصبرِ لتنال هذا الحظّ.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الصبرُ للتوفيقِ لدفعِ السيّئةِ بالحسنى، فهو حظٌّ عظيم."},"action":{"text":"تأمّل عظمَ خصلةِ دفعِ السيّئةِ بالحسنى: وما يُلقّى هذه الخصلةَ العظيمةَ ويُوفَّق لها إلا الذين صبروا على أذى الناسِ وكظمِ الغيظِ وترْكِ الانتقام؛ وما يُلقّاها إلا ذو حظٍّ عظيمٍ ونصيبٍ وافرٍ من الخيرِ والكمال «وما يلقاها إلا الذين صبروا وما يلقاها إلا ذو حظ عظيم»؛ ففي هذا بيانُ أنّ دفعَ السيّئةِ بالحسنى خصلةٌ عظيمةٌ لا يُوفَّق لها إلا الصابرون أصحابُ الحظِّ العظيم؛ فهي تحتاج صبرًا عظيمًا على كظمِ الغيظِ وترْكِ الانتقامِ والإحسانِ إلى المسيء؛ فاصبر لتُوفَّق لدفعِ السيّئةِ بالحسنى؛ فإنها لا تُنال إلا بالصبرِ ومجاهدةِ النفس؛ فمن صبر على الأذى، وكظم غيظه، وأحسن إلى من أساء إليه، فقد نال حظًّا عظيمًا؛ فهذه الخصلةُ من أعلى مراتبِ الكمالِ والأخلاق؛ فتحلَّ بالصبرِ ومجاهدةِ النفسِ لتنال هذا الحظَّ العظيم؛ فراقب نفسك عند الإساءةِ إليك: هل تنتقم أم تصبر وتحسن؟ فجاهد نفسك على الصبرِ والإحسان؛ فمن صبر وأحسن نال الحظَّ العظيم؛ فاطلب هذا الحظَّ بالصبرِ ومجاهدةِ النفسِ على الإحسانِ إلى المسيء؛ فبالصبرِ تُنال أعلى الأخلاقِ وأعظمُ الحظوظ."}},{"n":36,"reflection":{"text":"«وإما ينزغنك من الشيطان نزغ فاستعذ بالله إنه هو السميع العليم»، وإن نزغك من الشيطانِ نزغٌ يصرفك عن الحلمِ والإحسان، فاستعذ بالله، إنه السميعُ العليم؛ ففي هذا علاجُ نزغِ الشيطانِ بالاستعاذة؛ فإذا وسوس لك الشيطانُ بالغضبِ والانتقام، فاستعذ بالله؛ فالاستعاذةُ تدفع نزغَ الشيطان، فاجعل الاستعاذةَ سلاحك ضدّ وساوسِ الشيطان.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاستعاذةُ بالله عند نزغِ الشيطان، فهي علاجُ وساوسه."},"action":{"text":"تأمّل علاجَ نزغِ الشيطان: وإما ينزغنّك، يصيبنّك ويحرّكنّك، من الشيطانِ نزغٌ ووسوسةٌ تصرفك عن الحلمِ والإحسانِ ودفعِ السيّئةِ بالحسنى، وتحملك على الغضبِ والانتقام، فاستعذ بالله والجأ إليه؛ إنه هو السميعُ لاستعاذتك، العليمُ بحالك وبكيدِ الشيطان «وإما ينزغنك من الشيطان نزغ فاستعذ بالله إنه هو السميع العليم»؛ ففي هذا علاجُ نزغِ الشيطانِ ووسوسته بالاستعاذةِ بالله؛ فالشيطانُ يحرّض على الغضبِ والانتقامِ والإساءة، ويصدّ عن الحلمِ والإحسان؛ فإذا وسوس لك الشيطانُ بالغضبِ والانتقامِ أو بأيِّ معصية، فاستعذ بالله منه؛ قل أعوذ بالله من الشيطانِ الرجيم؛ فالاستعاذةُ بالله تدفع نزغَ الشيطانِ ووسوسته؛ فمن استعاذ بالله بصدقٍ أعاذه وكفاه شرَّ الشيطان؛ فاجعل الاستعاذةَ بالله سلاحك ضدّ وساوسِ الشيطانِ ونزغاته؛ وإذا غضبت فاستعذ بالله واسكت؛ فإنّ الغضبَ من الشيطان؛ فبالاستعاذةِ يُدفَع كيدُ الشيطان؛ فإنه هو السميعُ لدعائك، العليمُ بحالك؛ فالجأ إليه، واستعذ به، عند كلِّ نزغٍ ووسوسة؛ فبالاستعاذةِ تُطفأ نارُ الغضب، ويُدفَع كيدُ الشيطان، وتُوفَّق للحلمِ والإحسان."}}]},{"title":"آياتُ الله في الليلِ والنهارِ والشمسِ والقمرِ والأرضِ الميتة، والإلحادُ في الآيات","range":[37,40],"theme":"أنّ من آياتِ الله الليلَ والنهارَ والشمسَ والقمرَ فلا يُسجَد لها بل لخالقها، وأنّ الملائكةَ عند الله يسبّحون بلا سأم (سجدة)، وأنّ من آياته إحياءَ الأرضِ الميتةِ بالماءِ دليلًا على البعث، وأنّ الملحدين في آياته لا يخفون عليه والموازنةُ بين من يُلقى في النارِ ومن يأتي آمنًا","verses":[{"n":37,"reflection":{"text":"«ومن آياته الليل والنهار والشمس والقمر لا تسجدوا للشمس ولا للقمر واسجدوا لله الذي خلقهن إن كنتم إياه تعبدون»، ومن آياتِ الله الليلُ والنهارُ والشمسُ والقمر، لا تسجدوا للشمسِ ولا للقمر، واسجدوا لله الذي خلقهنّ إن كنتم إيّاه تعبدون؛ ففي هذا الاستدلالُ بالآياتِ على توحيدِ الخالق؛ فاسجد لله خالقِ الشمسِ والقمر، لا للمخلوقات، فالعبادةُ للخالقِ لا للمخلوق، فوحّد الخالقَ واسجد له وحده.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"السجودُ لله خالقِ الآيات، لا للمخلوقات، وتوحيدُ الخالق."},"action":{"text":"تأمّل الاستدلالَ بآياتِ الله على توحيده: ومن آياتِ الله الدالّةِ على قدرته ووحدانيّته: الليلُ والنهارُ بتعاقبهما، والشمسُ والقمرُ بجريهما ونظامهما؛ لا تسجدوا للشمسِ ولا للقمرِ فإنهما مخلوقان مسخّران، واسجدوا لله وحده الذي خلقهنّ، إن كنتم إيّاه تعبدون حقًّا «ومن آياته الليل والنهار والشمس والقمر لا تسجدوا للشمس ولا للقمر واسجدوا لله الذي خلقهن إن كنتم إياه تعبدون»؛ ففي هذا الاستدلالُ بالآياتِ الكونيةِ على توحيدِ الخالقِ واستحقاقِه للعبادة؛ فالشمسُ والقمرُ آيتان مخلوقتان مسخّرتان، لا تستحقّان العبادة؛ فمن عبد الشمسَ أو القمرَ فقد عبد مخلوقًا عاجزًا؛ فاسجد لله خالقِ الشمسِ والقمرِ والليلِ والنهار، لا للمخلوقات؛ فالعبادةُ حقٌّ للخالقِ وحده، لا للمخلوق؛ فوحّد الخالقَ، واسجد له وحده؛ فتأمّل في هذه الآياتِ العظيمةِ لتزداد يقينًا بعظمةِ خالقها؛ فمن خلق الشمسَ والقمرَ والليلَ والنهارَ هو المستحقُّ للسجودِ والعبادة؛ فأخلص السجودَ والعبادةَ لله خالقِ كلِّ شيء؛ ولا تصرف شيئًا من العبادةِ لمخلوق؛ فاسجد لخالقِ الآيات، لا للآياتِ المخلوقة."}},{"n":38,"reflection":{"text":"«فإن استكبروا فالذين عند ربك يسبحون له بالليل والنهار وهم لا يسأمون»: فإن استكبروا عن عبادةِ الله، فالملائكةُ الذين عند ربّك يسبّحون له ليلًا ونهارًا لا يملّون؛ ففي هذا أنّ استكبارَ المستكبرين لا يضرّ الله؛ فاعلم أنّ الله غنيٌّ عن عبادة المستكبرين، وأنّ الملائكةَ تعبده بلا ملل، فاقتدِ بالملائكةِ في دوامِ العبادةِ بلا سأم، ولا تستكبر عن عبادةِ الله. (سجدةُ تلاوة)","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"دوامُ عبادةِ الله بلا ملل، اقتداءً بالملائكة، ونبذُ الاستكبار."},"action":{"text":"تأمّل بيانَ غنى الله عن عبادةِ المستكبرين: فإن استكبر هؤلاء المشركون عن عبادةِ الله والسجودِ له، فإنّ الله غنيٌّ عنهم؛ فالملائكةُ الذين عند ربّك، المقرّبون، يسبّحون له ويعبدونه بالليلِ والنهارِ دائمًا، وهم لا يسأمون ولا يملّون ولا يفترون «فإن استكبروا فالذين عند ربك يسبحون له بالليل والنهار وهم لا يسأمون»؛ (وهذا موضعُ سجدةِ تلاوة)؛ ففي هذا أنّ استكبارَ المستكبرين لا يضرّ الله شيئًا؛ فله عبادٌ من الملائكةِ يعبدونه بلا ملل؛ فاعلم أنّ الله غنيٌّ عن عبادةِ المستكبرين وعن الخلقِ أجمعين؛ فمن استكبر عن عبادته لم يضرّه، وإنما يضرّ نفسه؛ واقتدِ بالملائكةِ في دوامِ العبادةِ والتسبيحِ بلا سأمٍ ولا ملل؛ فهم يسبّحون الليلَ والنهارَ لا يفترون؛ فلا تملّ من عبادةِ الله وذكره وطاعته؛ بل داوم عليها بنشاطٍ ومحبّة؛ ولا تستكبر عن عبادةِ الله والسجودِ له؛ فالاستكبارُ عن العبادةِ سبيلُ الهلاك؛ فتواضع لله بالعبادةِ والسجود؛ واقتدِ بالملائكةِ في دوامِ التسبيحِ والطاعةِ بلا ملل؛ فمن داوم على عبادةِ الله بلا سأمٍ اقتداءً بالملائكةِ نال القربَ والرضا؛ فاسجد لله، واعبده، وداوم على ذلك بلا ملل."}},{"n":39,"reflection":{"text":"«ومن آياته أنك ترى الأرض خاشعة فإذا أنزلنا عليها الماء اهتزت وربت إن الذي أحياها لمحيي الموتى إنه على كل شيء قدير»، ومن آياته أنك ترى الأرضَ يابسةً هامدة، فإذا أنزلنا عليها الماءَ تحرّكت وانتفخت بالنبات، إنّ الذي أحياها لمحيي الموتى، إنه على كلِّ شيء قدير؛ ففي هذا الاستدلالُ بإحياءِ الأرضِ على البعث؛ فتأمّل إحياءَ الأرضِ الميتةِ بالماء، فمن أحياها يحيي الموتى، فأيقن بالبعثِ واستعدّ له، فالقادرُ على إحياءِ الأرضِ قادرٌ على إحيائك.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بالبعثِ استدلالًا بإحياءِ الأرضِ الميتة."},"action":{"text":"تأمّل آيةَ الله في إحياءِ الأرض: ومن آياته الدالّةِ على قدرته والبعث: أنك ترى الأرضَ خاشعةً يابسةً هامدةً لا نباتَ فيها، فإذا أنزلنا عليها الماءَ، المطر، اهتزّت وتحرّكت بالنبات، وربت وانتفخت وعلت بالزرعِ والخير؛ إنّ الذي أحيا هذه الأرضَ الميتةَ لقادرٌ على إحياءِ الموتى وبعثهم، إنه على كلِّ شيء قدير «ومن آياته أنك ترى الأرض خاشعة فإذا أنزلنا عليها الماء اهتزت وربت إن الذي أحياها لمحيي الموتى إنه على كل شيء قدير»؛ ففي هذا الاستدلالُ بإحياءِ الأرضِ الميتةِ على قدرةِ الله على البعث؛ فتأمّل الأرضَ الميتةَ كيف تحيا بالماءِ فتخضرّ وتنبت؛ فمن أحيا الأرضَ الميتةَ قادرٌ على أن يحييَ الموتى ويبعثهم؛ وترى الأرضَ هامدةً فإذا أنزلنا عليها الماءَ اهتزّت وربت وأنبتت من كلِّ زوجٍ بهيج ذلك بأنّ الله هو الحق وأنه يحيي الموتى؛ فأيقن بالبعثِ الذي هو حقٌّ لا ريبَ فيه؛ واستعدّ له بالإيمانِ والعملِ الصالح؛ فالقادرُ على إحياءِ الأرضِ الميتةِ قادرٌ على إحيائك بعد موتك؛ فمن تأمّل إحياءَ الأرضِ أيقن بالبعثِ وقدرةِ الله؛ فاجعل من مشهدِ الأرضِ التي تحيا بعد موتها دليلًا يقوّي يقينك بالبعثِ ويحملك على الاستعدادِ له."}},{"n":40,"reflection":{"text":"«إن الذين يلحدون في آياتنا لا يخفون علينا أفمن يلقى في النار خير أم من يأتي آمنا يوم القيامة اعملوا ما شئتم إنه بما تعملون بصير»: إنّ الذين يميلون عن الحقِّ في آياتِنا لا يخفون علينا، أفمن يُلقى في النارِ خيرٌ أم من يأتي آمنًا يومَ القيامة؟ اعملوا ما شئتم إنه بما تعملون بصير؛ ففي هذا وعيدُ الملحدين في الآياتِ والموازنةُ بين الفريقين؛ فاحذر الإلحادَ في آياتِ الله، واعمل لتأتيَ آمنًا يومَ القيامة، فالله بصيرٌ بعملك، فراقبه واعمل صالحًا لتنجو من النار.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الإلحادِ في الآيات، والعملُ للأمنِ يومَ القيامة."},"action":{"text":"تأمّل وعيدَ الملحدين والموازنةَ بين الفريقين: إنّ الذين يلحدون في آياتِنا، يميلون بها عن الحقِّ بالتحريفِ والتكذيبِ والتأويلِ الباطل، لا يخفون علينا، بل نعلمهم ونجازيهم؛ أفمن يُلقى في النارِ خيرٌ أم من يأتي آمنًا يومَ القيامة؟ لا يستويان؛ اعملوا ما شئتم من خيرٍ أو شرٍّ، تهديدًا، إنه بما تعملون بصيرٌ لا يخفى عليه شيء «إن الذين يلحدون في آياتنا لا يخفون علينا أفمن يلقى في النار خير أم من يأتي آمنا يوم القيامة اعملوا ما شئتم إنه بما تعملون بصير»؛ ففي هذا وعيدُ الملحدين في آياتِ الله، والموازنةُ بين من يُلقى في النارِ ومن يأتي آمنًا؛ فاحذر الإلحادَ في آياتِ الله بالتحريفِ أو التكذيبِ أو التأويلِ الباطلِ أو الطعن؛ فإنّ الملحدين لا يخفون على الله؛ واعمل لتكون ممّن يأتي آمنًا يومَ القيامة، لا ممّن يُلقى في النار؛ فراقب الله في عملك، فإنه بصيرٌ بما تعمل؛ اعملوا ما شئتم إنه بما تعملون بصير؛ فهذا تهديدٌ لمن يعمل السوء؛ فاعمل صالحًا لتنجو من النارِ وتأتيَ آمنًا؛ فالله بصيرٌ بأعمالك كلِّها؛ فمن راقب الله وعمل صالحًا أتى آمنًا، ومن ألحد وأساء أُلقي في النار؛ فاختر لنفسك الأمنَ يومَ القيامةِ بالإيمانِ والعملِ الصالحِ وتعظيمِ آياتِ الله."}}]},{"title":"عزّةُ القرآنِ وأنه هدًى وشفاء، والاختلافُ في الكتب، وأنّ الجزاءَ بالعمل","range":[41,46],"theme":"وعيدُ من كفر بالقرآنِ وأنه كتابٌ عزيزٌ لا يأتيه الباطلُ من بين يديه ولا من خلفه تنزيلٌ من حكيمٍ حميد، وتسليةُ النبيِّ بأنّ ما قيل له قد قيل للرسلِ وأنّ ربه ذو مغفرةٍ وعقاب، وأنه لو كان أعجميًّا لاعترضوا وأنه للمؤمنين هدًى وشفاءٌ وللكافرين عمًى، وأنّ التوراةَ اختُلِف فيها، وأنّ من عمل صالحًا فلنفسه وما ربك بظلّامٍ للعبيد","verses":[{"n":41,"reflection":{"text":"«إن الذين كفروا بالذكر لما جاءهم وإنه لكتاب عزيز»: إنّ الذين كفروا بالقرآنِ لمّا جاءهم (لهم عذابٌ شديد)، وإنه لكتابٌ عزيزٌ منيعٌ لا يُدرَك ولا يُغلَب؛ ففي هذا وعيدُ من كفر بالقرآن وبيانُ عزّته؛ فعظّم القرآنَ الكتابَ العزيز، ولا تكفر به، فمن كفر بالقرآنِ خسر، ومن آمن به عزّ، فآمن بالقرآنِ العزيزِ واعتزَّ به.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإيمانُ بالقرآنِ العزيزِ وتعظيمُه، والحذرُ من الكفرِ به."},"action":{"text":"تأمّل وعيدَ من كفر بالقرآنِ وبيانَ عزّته: إنّ الذين كفروا بالذكرِ، القرآنِ، لمّا جاءهم، فجحدوه وكذّبوا به، لهم عذابٌ شديد؛ وإنه لكتابٌ عزيزٌ منيعٌ كريمٌ، لا يُدرَك ولا يُغلَب ولا يُعارَض، محفوظٌ من التغييرِ والتبديل «إن الذين كفروا بالذكر لما جاءهم وإنه لكتاب عزيز»؛ ففي هذا وعيدُ من كفر بالقرآن، وبيانُ عزّتِه ومنعته؛ فالقرآنُ كتابٌ عزيزٌ، أعزّه الله وحفظه؛ إنا نحن نزّلنا الذكرَ وإنا له لحافظون؛ فعظّم القرآنَ الكتابَ العزيزَ في قلبك؛ ولا تكفر به، ولا تجحده، ولا تعرض عنه؛ فمن كفر بالقرآنِ خسر خسرانًا مبينًا، ومن آمن به عزّ وسعد؛ فآمن بالقرآنِ العزيز، وصدّق به، وأقبل عليه بالتلاوةِ والتدبّرِ والعملِ والتحكيم؛ واعتزَّ به؛ فمن اعتزّ بالقرآنِ أعزّه الله؛ ومن كان القرآنُ إمامه سعد؛ فاجعل القرآنَ العزيزَ إمامك ودليلك وعزّك؛ فبالإيمانِ به وتعظيمِه والعملِ به تُنال العزّةُ والهداية؛ فلا تكن من الكافرين به الذين لهم عذابٌ شديد؛ بل كن من المؤمنين به المعتزّين به."}},{"n":42,"reflection":{"text":"«لا يأتيه الباطل من بين يديه ولا من خلفه تنزيل من حكيم حميد»: لا يأتيه الباطلُ من أيِّ جهة، تنزيلٌ من حكيمٍ حميد؛ ففي هذا بيانُ حفظِ القرآنِ من الباطلِ وكمالِ مصدرِه؛ فاطمئنّ إلى القرآنِ الذي لا يأتيه الباطل، واعتمد عليه، فالقرآنُ محفوظٌ من الباطلِ كلِّه، فاجعله حجّتك ومرجعك، فهو تنزيلٌ من حكيمٍ حميد.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاطمئنانُ إلى القرآنِ المحفوظِ من الباطل، والاعتمادُ عليه."},"action":{"text":"تأمّل كمالَ القرآنِ وحفظه: لا يأتيه الباطلُ من بين يديه ولا من خلفه، أي لا يتطرّق إليه الباطلُ من أيِّ جهةٍ ولا بأيِّ وجه، لا في أخباره فتكون كاذبة، ولا في أحكامه فتكون جائرة، ولا يُنسَخ ولا يُبدَّل ولا يُحرَّف؛ تنزيلٌ من حكيمٍ في أقواله وأفعاله، حميدٍ في ذاته وصفاته «لا يأتيه الباطل من بين يديه ولا من خلفه تنزيل من حكيم حميد»؛ ففي هذا بيانُ حفظِ القرآنِ من الباطلِ كلِّه، وكمالِ مصدرِه؛ فالقرآنُ حقٌّ كلُّه، محفوظٌ من الباطلِ من كلِّ وجه؛ فأخباره صدق، وأحكامه عدل، وهو محفوظٌ من التحريفِ والتبديل؛ فاطمئنّ إلى القرآنِ الذي لا يأتيه الباطل؛ واعتمد عليه، وثق به، واجعله حجّتك ومرجعك في كلِّ أمر؛ فما وافق القرآنَ فهو حق، وما خالفه فهو باطل؛ فالقرآنُ ميزانُ الحقِّ والباطل؛ فاجعله حاكمًا في اعتقادك وقولك وعملك؛ فهو تنزيلٌ من حكيمٍ حميد؛ فمن اعتصم بالقرآنِ اهتدى، ومن أعرض عنه ضلّ؛ فتمسّك بالقرآنِ المحفوظِ من الباطل؛ واطمئنّ إليه، واعتمد عليه؛ فهو حبلُ الله المتين، وصراطُه المستقيم، لا يأتيه الباطلُ أبدًا."}},{"n":43,"reflection":{"text":"«ما يقال لك إلا ما قد قيل للرسل من قبلك إن ربك لذو مغفرة وذو عقاب أليم»: ما يُقال لك يا محمدُ من التكذيبِ إلا مثلُ ما قيل للرسلِ قبلك، إنّ ربّك لذو مغفرةٍ وذو عقابٍ أليم؛ ففي هذا تسليةُ النبيِّ والجمعُ بين المغفرةِ والعقاب؛ فاصبر على الأذى كما صبر الرسل، وارجُ مغفرةَ الله واحذر عقابه، فالله يغفر للتائبين ويعاقب المصرّين، فاجمع بين الرجاءِ والخوف.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الصبرُ على الأذى تأسّيًا بالرسل، والجمعُ بين الرجاءِ والخوف."},"action":{"text":"تأمّل تسليةَ الله لنبيّه: ما يُقال لك يا محمدُ من التكذيبِ والأذى والاتّهامِ إلا مثلُ ما قد قيل للرسلِ من قبلك؛ فقد كُذّبوا وأُوذوا فصبروا؛ إنّ ربّك لذو مغفرةٍ واسعةٍ للتائبين، وذو عقابٍ أليمٍ للمصرّين المكذّبين «ما يقال لك إلا ما قد قيل للرسل من قبلك إن ربك لذو مغفرة وذو عقاب أليم»؛ ففي هذا تسليةُ النبيِّ ﷺ بما لقيه الرسلُ من قبله، والجمعُ بين صفةِ المغفرةِ وصفةِ العقاب؛ فاصبر على أذى المكذّبين وتكذيبهم، تأسّيًا بالرسلِ من قبلك؛ فما لقيت من أذًى فقد لقي الرسلُ مثله فصبروا؛ ولقد كُذّبت رسلٌ من قبلك فصبروا على ما كُذّبوا وأوذوا؛ فتأسَّ بهم في الصبر؛ واعلم أنّ ربّك ذو مغفرةٍ وذو عقاب؛ فارجُ مغفرته إن أذنبت وتبت، واحذر عقابه إن أصررت؛ فاجمع في قلبك بين الرجاءِ والخوف؛ فمن جمع بينهما استقام سيره؛ فالله يغفر للتائبين المنيبين، ويعاقب المصرّين المعاندين؛ فتب إليه راجيًا مغفرته، واجتنب المعاصيَ خائفًا عقابه؛ فاعبد الله راجيًا خائفًا؛ فبالرجاءِ تُقبِل على الطاعة، وبالخوفِ تجتنب المعصية."}},{"n":44,"reflection":{"text":"«ولو جعلناه قرآنا أعجميا لقالوا لولا فصلت آياته أأعجمي وعربي قل هو للذين آمنوا هدى وشفاء والذين لا يؤمنون في آذانهم وقر وهو عليهم عمى أولئك ينادون من مكان بعيد»، ولو جعلنا القرآنَ أعجميًّا لقالوا: هلّا فُصّلت آياته! أقرآنٌ أعجميٌّ ورسولٌ عربي؟ قل هو للمؤمنين هدًى وشفاء، والذين لا يؤمنون في آذانهم صمم وهو عليهم عمى، أولئك يُنادَون من مكانٍ بعيد؛ ففي هذا بيانُ أنّ القرآنَ هدًى وشفاءٌ للمؤمنين، عمًى على غيرهم؛ فاجعل القرآنَ هدًى وشفاءً لقلبك بالإيمانِ والإقبال، فمن آمن انتفع به، ومن أعرض حُرِم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"جعلُ القرآنِ هدًى وشفاءً بالإيمانِ والإقبال عليه."},"action":{"text":"تأمّل بيانَ حكمةِ إنزالِ القرآنِ عربيًّا: ولو جعلنا القرآنَ أعجميًّا بلغةٍ غيرِ العربيةِ لقال المشركون معترضين: هلّا فُصّلت آياته وبُيّنت بلغتنا! أينزَّل قرآنٌ أعجميٌّ على رسولٍ عربيٍّ وقومٍ عرب؟ فأنزله الله عربيًّا مبينًا قطعًا لحجّتهم؛ قل هو للذين آمنوا هدًى يهديهم، وشفاءٌ لما في صدورهم من الشكِّ والأمراض؛ والذين لا يؤمنون في آذانهم وقرٌ وصممٌ عن سماعه، وهو عليهم عمًى لا يبصرون به الحق؛ أولئك كأنهم يُنادَون من مكانٍ بعيدٍ فلا يسمعون ولا يفهمون «ولو جعلناه قرآنا أعجميا... قل هو للذين آمنوا هدى وشفاء والذين لا يؤمنون في آذانهم وقر وهو عليهم عمى أولئك ينادون من مكان بعيد»؛ ففي هذا بيانُ أنّ القرآنَ هدًى وشفاءٌ للمؤمنين، وأنه عمًى وصممٌ على المعرضين؛ فالقرآنُ واحد، لكن أثره يختلف بحسبِ القلوب؛ فهو هدًى وشفاءٌ لمن آمن وأقبل، وعمًى وحسرةٌ على من كفر وأعرض؛ وننزّل من القرآنِ ما هو شفاءٌ ورحمةٌ للمؤمنين ولا يزيد الظالمين إلا خسارًا؛ فاجعل القرآنَ هدًى وشفاءً لقلبك بالإيمانِ به والإقبالِ عليه والتدبّرِ له والعملِ به؛ فمن آمن بالقرآنِ وأقبل عليه اهتدى به وشُفِي قلبه؛ ومن أعرض عنه حُرِم هداه وشفاءه؛ فاطلب الهدايةَ والشفاءَ من القرآن بالإيمانِ والإقبال؛ فهو شفاءُ القلوبِ من أمراضِ الشكِّ والشهواتِ والشبهات؛ فأقبل عليه مؤمنًا، لينفعك هدًى وشفاء."}},{"n":45,"reflection":{"text":"«ولقد آتينا موسى الكتاب فاختلف فيه ولولا كلمة سبقت من ربك لقضي بينهم وإنهم لفي شك منه مريب»، ولقد آتينا موسى الكتابَ فاختُلِف فيه، ولولا كلمةٌ سبقت من ربّك بتأخيرِ العذابِ لقُضِي بينهم، وإنهم لفي شكٍّ منه مريب؛ ففي هذا تسليةُ النبيِّ بأنّ الاختلافَ في الكتبِ قديم؛ فاعلم أنّ الاختلافَ في الحقِّ سنّةٌ ماضية، فلا يحزنك اختلافُ الناسِ في القرآن، بل اثبت على الحقِّ ولا تكن من الشاكّين المرتابين.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الثباتُ على الحق، وتركُ الشكِّ والارتياب، وإدراكُ أنّ الاختلافَ قديم."},"action":{"text":"تأمّل تسليةَ الله لنبيّه بما جرى لموسى: ولقد آتينا موسى الكتابَ، التوراة، فاختُلِف فيه، فآمن به قومٌ وكفر به آخرون، كما اختُلِف في القرآن؛ ولولا كلمةٌ سبقت من ربّك بتأخيرِ العذابِ عن هذه الأمّةِ إلى أجلٍ مسمًّى لقُضِي بينهم وعُجّل عذابُ المكذّبين؛ وإنهم، المكذّبين، لفي شكٍّ من القرآنِ مريبٍ موقعٍ في الريبة «ولقد آتينا موسى الكتاب فاختلف فيه ولولا كلمة سبقت من ربك لقضي بينهم وإنهم لفي شك منه مريب»؛ ففي هذا تسليةُ النبيِّ ﷺ بأنّ الاختلافَ في الكتبِ السماويةِ قديم؛ فقد اختُلِف في التوراةِ كما اختُلِف في القرآن؛ فاعلم أنّ الاختلافَ في الحقِّ وتكذيبَ بعضِ الناسِ به سنّةٌ ماضيةٌ في الأمم؛ فلا يحزنك اختلافُ الناسِ في القرآنِ وتكذيبُ بعضهم به؛ بل اثبت على الحقِّ الذي أنت عليه؛ ولا تكن من الشاكّين المرتابين في الحق؛ فالحقُّ لا يتغيّر باختلافِ الناسِ فيه؛ فاثبت على اليقينِ، واطرح الشكَّ والريب؛ فمن ثبت على الحقِّ بيقينٍ نجا، ومن شكّ فيه وارتاب ضلّ؛ فاجعل إيمانك بالقرآنِ يقينًا لا شكَّ فيه؛ ولا يزعزعك اختلافُ المختلفين ولا تكذيبُ المكذّبين؛ فالعاقبةُ للحقِّ وأهله."}},{"n":46,"reflection":{"text":"«من عمل صالحا فلنفسه ومن أساء فعليها وما ربك بظلام للعبيد»: من عمل صالحًا فلنفسه، ومن أساء فعليها، وما ربّك بظلّامٍ للعبيد؛ ففي هذا تقريرُ عدلِ الله وأنّ الجزاءَ بالعمل؛ فاعمل صالحًا فنفعه لك، واجتنب الإساءةَ فضررها عليك، واعلم أنّ الله عدلٌ لا يظلم، فاعمل لنفسك خيرًا، فالله لا يظلم أحدًا.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ الصالحُ للنفس، وإدراكُ عدلِ الله الذي لا يظلم."},"action":{"text":"تأمّل تقريرَ الله لعدله: من عمل صالحًا فلنفسه ونفعُ عمله يعود عليه، ومن أساء وعمل سوءًا فعليها وضرَرُ عمله يعود عليه؛ وما ربّك بظلّامٍ للعبيدِ، فلا يعاقب أحدًا بغيرِ ذنب، ولا ينقص من أجرِ محسنٍ شيئًا «من عمل صالحا فلنفسه ومن أساء فعليها وما ربك بظلام للعبيد»؛ ففي هذا تقريرُ عدلِ الله، وأنّ الجزاءَ بالعمل، وأنّ نفعَ الطاعةِ وضررَ المعصيةِ يعودان على العامل؛ فاعمل صالحًا فإنّ نفعه لك أنت؛ إن أحسنتم أحسنتم لأنفسكم؛ واجتنب الإساءةَ والمعصيةَ فإنّ ضررها عليك أنت؛ وإن أسأتم فلها؛ فلا تظنّ أنك تنفع الله بطاعتك أو تضرّه بمعصيتك؛ فالله غنيٌّ عنك؛ إنما ينفعك عملك الصالح، ويضرّك عملك السيّئ؛ واعلم أنّ الله عدلٌ لا يظلم أحدًا مثقالَ ذرّة؛ إنّ الله لا يظلم الناسَ شيئًا؛ فما ربّك بظلّامٍ للعبيد؛ فاعمل لنفسك خيرًا، واجتنب ما يضرّها؛ فأنت تعمل لنفسك، لا لغيرك؛ فمن عمل صالحًا فاز، ومن أساء خسر؛ والله لا يظلم أحدًا، بل يجازي كلًّا بعمله بعدلٍ وفضل؛ فاجعل عملك صالحًا ينفعك، واجتنب السوءَ الذي يضرّك."}}]},{"title":"علمُ الساعةِ عند الله، وتقلّبُ الإنسان، وختامُ سنريهم آياتنا في الآفاق","range":[47,54],"theme":"أنّ علمَ الساعةِ يُردّ إليه وحده وأنّ كلَّ ثمرةٍ وحملٍ بعلمه وتبرّؤُ المشركين من شركهم يومَ القيامة وضلالُ معبوداتهم عنهم، وذمُّ الإنسانِ الذي لا يسأم من دعاءِ الخيرِ وييأس عند الشرِّ ويبطر عند النعمةِ ويعرض ويلجأ عند الشدّة، وتنبيهُ المكذّبين على خطرِ الكفرِ بالحقّ، وختامُ السورةِ بوعدِ إراءةِ الآياتِ في الآفاقِ والأنفسِ حتى يتبيّن أنه الحق، وأنّ الله شهيدٌ على كلِّ شيءٍ محيطٌ به وأنهم في مريةٍ من لقائه","verses":[{"n":47,"reflection":{"text":"«إليه يرد علم الساعة وما تخرج من ثمرات من أكمامها وما تحمل من أنثى ولا تضع إلا بعلمه ويوم يناديهم أين شركائي قالوا آذناك ما منا من شهيد»: إليه وحده يُردّ علمُ الساعة، وما تخرج ثمرةٌ من غلافها وما تحمل أنثى ولا تضع إلا بعلمه، ويومَ يناديهم: أين شركائي؟ قالوا: أعلمناك ما منّا من شاهدٍ بأنّ لك شريكًا؛ ففي هذا إحاطةُ علمِ الله وتبرّؤُ المشركين من شركهم؛ فاعلم أنّ علمَ الله محيطٌ بكلِّ شيء، ووحّده وحده، فمن أحاط علمه بكلِّ شيءٍ هو المستحقُّ للعبادة، فأخلص له التوحيد.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بإحاطةِ علمِ الله بكلِّ شيء، وإخلاصُ التوحيدِ له."},"action":{"text":"تأمّل إحاطةَ علمِ الله: إليه وحده يُردّ علمُ الساعةِ فلا يعلم وقتها إلا هو؛ وما تخرج من ثمرةٍ من غلافها وكِمامها، وما تحمل من أنثى ولا تضع حملها إلا بعلمه المحيط؛ ويومَ القيامةِ يناديهم توبيخًا: أين شركائي الذين كنتم تزعمونهم وتعبدونهم؟ قالوا: أعلمناك وأخبرناك، ما منّا من شاهدٍ يشهد بأنّ لك شريكًا، فقد تبرّأنا من الشرك «إليه يرد علم الساعة وما تخرج من ثمرات من أكمامها وما تحمل من أنثى ولا تضع إلا بعلمه ويوم يناديهم أين شركائي قالوا آذناك ما منا من شهيد»؛ ففي هذا بيانُ إحاطةِ علمِ الله بكلِّ شيء، بوقتِ الساعةِ، وبكلِّ ثمرةٍ وحمل، وتبرّؤُ المشركين من شركهم يومَ القيامة؛ فعلمُ الله محيطٌ بالغيبِ والشهادة، بالكلّيّاتِ والجزئيّات؛ فلا يخرج شيءٌ عن علمه؛ فاعلم أنّ علمَ الله محيطٌ بكلِّ شيء، دقيقِه وجليله؛ وعنده مفاتحُ الغيبِ لا يعلمها إلا هو؛ وما تسقط من ورقةٍ إلا يعلمها؛ فمن أحاط علمه بكلِّ شيءٍ هو المستحقُّ للعبادةِ وحده؛ فوحّده، وأخلص له التوحيدَ والعبادة؛ ولا تشرك به شيئًا؛ فإنّ المشركين سيتبرّؤون من شركهم يومَ القيامة؛ فلا تعبد ما ستتبرّأ منه؛ بل وحّد العليمَ المحيطَ بكلِّ شيء؛ فراقبه في كلِّ حال، فإنه يعلم سرّك وعلنك."}},{"n":48,"reflection":{"text":"«وضل عنهم ما كانوا يدعون من قبل وظنوا ما لهم من محيص»، وغاب عنهم ما كانوا يعبدون من دونِ الله، وأيقنوا أنه لا مهربَ لهم من العذاب؛ ففي هذا تخلّي المعبوداتِ عن عابديها وإحاطةُ العذابِ بهم؛ فاحذر أن تعبد ما يتخلّى عنك يومَ حاجتك، وتوحّد الله الذي لا يتخلّى عنك، فمن عبد غيرَ الله ضلّ عنه معبوده يومَ القيامة، فوحّد الله لتنجو.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"توحيدُ الله، والحذرُ من عبادةِ ما يتخلّى عن عابده يومَ القيامة."},"action":{"text":"تأمّل حالَ المشركين عند العذاب: وضلّ وغاب عنهم ما كانوا يدعون ويعبدون من دونِ الله من الأصنامِ والأنداد، فلم تنفعهم ولم تشفع لهم؛ وأيقنوا وظنّوا يقينًا أنه ما لهم من محيصٍ ومهربٍ ومنجًى من العذاب «وضل عنهم ما كانوا يدعون من قبل وظنوا ما لهم من محيص»؛ ففي هذا تخلّي المعبوداتِ الباطلةِ عن عابديها يومَ القيامة، وإحاطةُ العذابِ بهم بلا مهرب؛ فتغيب عنهم آلهتهم حين يحتاجون إليها، ويوقنون أنه لا مفرَّ من العذاب؛ فاحذر أن تعبد ما يتخلّى عنك ويضلّ عنك يومَ حاجتك إليه؛ فكلُّ معبودٍ سوى الله سيتخلّى عن عابده يومَ القيامة؛ ويومَ القيامةِ يكفرون بشرككم؛ فلا تتعلّق بمن لا ينفعك يومَ الشدّة؛ بل توحّد الله الذي لا يتخلّى عن عبده المؤمن في الدنيا والآخرة؛ فمن عبد غيرَ الله ضلّ عنه معبوده يومَ القيامةِ ولم يجد محيصًا؛ ومن عبد الله وحده نفعه ونجّاه؛ فوحّد الله، وأخلص له العبادة؛ فهو وحده الذي ينفع ويضرّ، ولا يتخلّى عن عابده؛ فاجعل عبادتك وتعلّقك بالله وحده؛ فبه النجاةُ والمحيص، وبعبادةِ غيره الضلالُ والهلاك."}},{"n":49,"reflection":{"text":"«لا يسأم الإنسان من دعاء الخير وإن مسه الشر فيئوس قنوط»: لا يملّ الإنسانُ من طلبِ الخيرِ (المالِ والصحّة)، وإن أصابه الشرُّ فيئوسٌ قنوطٌ من رحمةِ الله؛ ففي هذا ذمُّ حرصِ الإنسانِ ويأسِه؛ فاحذر الحرصَ الشديدَ على الدنيا واليأسَ عند الشدّة، بل اعتدل في طلبِ الخير، وأحسن الظنَّ بالله عند الشدّة، فلا تيأس من رحمةِ الله مهما اشتدّ البلاء.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاعتدالُ في طلبِ الخير، وعدمُ اليأسِ من رحمةِ الله عند الشدّة."},"action":{"text":"تأمّل ذمَّ الله لطبعِ الإنسانِ الجاحد: لا يسأم الإنسانُ ولا يملّ من دعاءِ الخيرِ وطلبه، من المالِ والصحّةِ والنعمة، بل هو حريصٌ عليه لا يشبع؛ وإن مسّه الشرُّ، الفقرُ أو المرضُ أو الشدّة، فيئوسٌ قنوطٌ من رحمةِ الله، شديدُ اليأسِ والقنوط «لا يسأم الإنسان من دعاء الخير وإن مسه الشر فيئوس قنوط»؛ ففي هذا ذمُّ حرصِ الإنسانِ على الدنيا ويأسِه عند الشدّة؛ فهو حريصٌ على الخيرِ لا يملّ من طلبه، يئوسٌ عند الشرِّ قنوط؛ فاحذر هذين الطبعين المذمومين: الحرصَ الشديدَ على الدنيا، واليأسَ من رحمةِ الله عند الشدّة؛ فاعتدل في طلبِ الخيرِ والدنيا؛ فلا تكن حريصًا لا تشبع؛ واقنع بما آتاك الله؛ وأحسن الظنَّ بالله عند الشدّةِ والبلاء؛ ولا تيأس من رحمةِ الله مهما اشتدّ عليك البلاء؛ ولا تيأسوا من روحِ الله؛ إنه لا ييأس من روحِ الله إلا القومُ الكافرون؛ فالمؤمنُ لا ييأس من رحمةِ الله في الشدّة، ولا يبطر عند النعمة؛ بل يشكر في الرخاء، ويصبر في البلاء، ويرجو رحمةَ الله في كلِّ حال؛ فاجعل حالك الاعتدالَ في طلبِ الخير، والرجاءَ لرحمةِ الله عند الشدّة؛ فمن أحسن الظنَّ بالله ورجا رحمته لم ييأس، ومن قنط من رحمته فقد أساء الظنَّ به."}},{"n":50,"reflection":{"text":"«ولئن أذقناه رحمة منا من بعد ضراء مسته ليقولن هذا لي وما أظن الساعة قائمة ولئن رجعت إلى ربي إن لي عنده للحسنى فلننبئن الذين كفروا بما عملوا ولنذيقنهم من عذاب غليظ»، ولئن أذقناه رحمةً من بعد ضرٍّ مسّه ليقولنّ: هذا لي باستحقاقي، وما أظنّ الساعةَ قائمة، ولئن رُجِعت إلى ربي إنّ لي عنده للحسنى، فلننبّئنّ الكافرين بما عملوا ولنذيقنّهم عذابًا غليظًا؛ ففي هذا ذمُّ بطرِ الإنسانِ عند النعمةِ وغروره؛ فاحذر البطرَ عند النعمةِ ونسبتها إلى نفسك، واشكر الله وأيقن بالساعة، فمن بطر عند النعمةِ وأنكر الآخرةَ عُذّب عذابًا غليظًا.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من البطرِ عند النعمة، وشكرُها واليقينُ بالآخرة."},"action":{"text":"تأمّل غرورَ الإنسانِ عند النعمة: ولئن أذقنا الإنسانَ رحمةً منّا، نعمةً وعافيةً وسعة، من بعد ضرٍّ وشدّةٍ مسّته، ليقولنّ بطرًا وغرورًا: هذا لي باستحقاقي وجدارتي، وما أظنّ الساعةَ قائمة، فأنكر البعث؛ ولئن رُجِعت إلى ربي، على سبيلِ الفرض، إنّ لي عنده للحسنى والجنّة، فتمنّى على الله الأمانيّ؛ فردّ الله عليه: فلننبّئنّ الذين كفروا بما عملوا يومَ القيامة، ولنذيقنّهم من عذابٍ غليظٍ شديد «ولئن أذقناه رحمة منا من بعد ضراء مسته ليقولن هذا لي وما أظن الساعة قائمة... فلننبئن الذين كفروا بما عملوا ولنذيقنهم من عذاب غليظ»؛ ففي هذا ذمُّ بطرِ الإنسانِ عند النعمةِ وغرورِه ونسيانِه للآخرة؛ فإذا أصابته النعمةُ نسبها إلى نفسه، وأنكر الساعة، وتمنّى على الله الأمانيّ الكاذبة؛ فاحذر البطرَ عند النعمةِ ونسبتها إلى نفسك واستحقاقك؛ بل اشكر الله ونسبها إلى فضله؛ وما بكم من نعمةٍ فمن الله؛ وأيقن بالساعةِ والبعثِ والجزاء؛ ولا تغترّ بالنعمةِ فتنسى الآخرة؛ ولا تتمنّ على الله الأمانيّ بلا عمل؛ فمن بطر عند النعمةِ وأنكر الآخرةَ واغترّ، فجزاؤه العذابُ الغليظ؛ فاشكر النعمةَ، وأيقن بالآخرة، واعمل لها؛ فبالشكرِ تدوم النعمة، وباليقينِ بالآخرةِ يستقيم العمل."}},{"n":51,"reflection":{"text":"«وإذا أنعمنا على الإنسان أعرض ونأى بجانبه وإذا مسه الشر فذو دعاء عريض»، وإذا أنعمنا على الإنسانِ أعرض عن الشكرِ والطاعةِ وتباعد، وإذا مسّه الشرُّ فذو دعاءٍ كثيرٍ واسع؛ ففي هذا ذمُّ تقلّبِ الإنسانِ بين النعمةِ والشدّة؛ فاحذر أن تعرض عن الله عند النعمةِ وتلجأ إليه عند الشدّة، بل اذكر الله واشكره في النعمة، كما تدعوه في الشدّة، فالوفاءُ في العبوديةِ في الحالين.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"ذكرُ الله وشكرُه في النعمة، لا الإعراضُ عنه إلا في الشدّة."},"action":{"text":"تأمّل ذمَّ الله لتقلّبِ الإنسان: وإذا أنعمنا على الإنسانِ بالصحّةِ والمالِ والعافية، أعرض عن الشكرِ والطاعةِ والدعاء، ونأى بجانبه وتباعد عن الله واستكبر؛ وإذا مسّه الشرُّ، الفقرُ أو المرضُ أو الشدّة، فذو دعاءٍ عريضٍ واسعٍ طويل، يُلحّ في الدعاءِ ويكثر منه «وإذا أنعمنا على الإنسان أعرض ونأى بجانبه وإذا مسه الشر فذو دعاء عريض»؛ ففي هذا ذمُّ تقلّبِ الإنسانِ بين النعمةِ والشدّة: يعرض عن الله في النعمة، ويلجأ إليه في الشدّة؛ فاحذر أن تكون ممّن يعرض عن الله عند النعمةِ والعافية، ثم يلجأ إليه ويدعوه عند الشدّةِ والبلاء؛ بل اذكر الله واشكره وادعه في النعمةِ والرخاء، كما تدعوه في الشدّةِ والبلاء؛ فالوفاءُ في العبوديةِ أن تعبد الله في الحالين؛ اذكر الله في الرخاءِ يذكرك في الشدّة؛ فمن عرف الله في الرخاءِ عرفه الله في الشدّة؛ فلا تكن ممّن يعرف الله في الضرّاءِ وينساه في السرّاء؛ بل كن وفيًّا في عبوديتك: شاكرًا في النعمة، صابرًا في البلاء، ذاكرًا داعيًا في الحالين؛ فراقب نفسك: هل تعرض عن الله عند النعمة؟ فتب من ذلك، والزم ذكره وشكره وطاعته دائمًا."}},{"n":52,"reflection":{"text":"«قل أرأيتم إن كان من عند الله ثم كفرتم به من أضل ممن هو في شقاق بعيد»: قل: أخبروني إن كان القرآنُ من عند الله ثم كفرتم به، من أضلُّ ممّن هو في خلافٍ ومعاندةٍ بعيدةٍ للحق؟ ففي هذا تنبيهُ المكذّبين على خطرِ الكفرِ بالحقِّ إن ثبت أنه من الله؛ فاحذر أن تكفر بالحقِّ فتكون في شقاقٍ بعيد، فتأمّل في الحقِّ قبل ردّه، فالكفرُ بما هو من عند الله أعظمُ الضلال.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"التأمّلُ في الحقِّ قبل ردّه، والحذرُ من الكفرِ بما هو من عند الله."},"action":{"text":"تأمّل تنبيهَ الله للمكذّبين: قل لهم يا محمدُ: أخبروني إن كان هذا القرآنُ من عند الله حقًّا، كما هو كذلك، ثم كفرتم به وجحدتموه، من أضلُّ وأخسرُ ممّن هو في شقاقٍ ومخالفةٍ ومعاندةٍ بعيدةٍ عن الحق؟ لا أحد أضلُّ منه «قل أرأيتم إن كان من عند الله ثم كفرتم به من أضل ممن هو في شقاق بعيد»؛ ففي هذا تنبيهُ المكذّبين على عظمِ خطرِ الكفرِ بالقرآنِ إن ثبت أنه من عند الله؛ فليتأمّلوا في عاقبةِ كفرهم إن كان القرآنُ حقًّا؛ فاحذر أن تكفر بالحقِّ أو تعرض عنه؛ فإنّ الكفرَ بما هو من عند الله أعظمُ الضلالِ والشقاق؛ فتأمّل في الحقِّ وتثبّت منه قبل ردّه أو الإعراضِ عنه؛ فإنّ ردَّ الحقِّ الذي من عند الله ضلالٌ بعيد؛ فلا تجازف بردِّ القرآنِ أو الإعراضِ عنه؛ بل تأمّل فيه، وتدبّر آياته، وانظر في براهينه؛ فإن تبيّن لك أنه حقٌّ فآمن به واتّبعه؛ فمن كفر بالحقِّ بعد تبيّنه فهو في شقاقٍ بعيدٍ وضلالٍ مبين؛ فبادر بالإيمانِ بالقرآنِ والتصديقِ به؛ ولا تكن من المعاندين الذين في شقاقٍ بعيد؛ فالسعيدُ من آمن بالحق، والشقيُّ من كفر به وعانده."}},{"n":53,"reflection":{"text":"«سنريهم آياتنا في الآفاق وفي أنفسهم حتى يتبين لهم أنه الحق أولم يكف بربك أنه على كل شيء شهيد»: سنريهم آياتنا في الآفاقِ (الكونِ) وفي أنفسهم حتى يتبيّن لهم أنّ القرآنَ حق، أولم يكفِ بربّك أنه على كلِّ شيء شهيد؟ ففي هذا وعدُ الله بإظهارِ آياتِه الدالّةِ على صدقِ القرآن؛ فتأمّل في آياتِ الله في الكونِ ونفسك، لتزداد يقينًا بأنّ القرآنَ حق، فآياتُ الله شاهدةٌ على صدقه، وكفى بالله شهيدًا.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"التأمّلُ في آياتِ الله في الآفاقِ والأنفس، لليقينِ بأنّ القرآنَ حق."},"action":{"text":"تأمّل هذا الوعدَ العظيمَ: سنري هؤلاء المكذّبين آياتِنا الدالّةَ على صدقِ القرآنِ في الآفاقِ، أقطارِ السماواتِ والأرضِ وما فيها من عجائبِ خلقِ الله، وفي أنفسهم، من بديعِ خلقهم وتكوينهم، حتى يتبيّن لهم يقينًا أنّ القرآنَ هو الحقُّ المنزّلُ من الله؛ أولم يكفِ بربّك أنه على كلِّ شيء شهيدٌ مطّلعٌ، فشهادته أعظمُ من كلِّ شهادة «سنريهم آياتنا في الآفاق وفي أنفسهم حتى يتبين لهم أنه الحق أولم يكف بربك أنه على كل شيء شهيد»؛ ففي هذا وعدُ الله بإظهارِ آياته في الكونِ والأنفسِ الدالّةِ على صدقِ القرآنِ وأنه الحق؛ فكلّما تقدّم الزمانُ ظهرت آياتٌ جديدةٌ تصدّق القرآنَ في الآفاقِ والأنفس؛ فتأمّل في آياتِ الله في الكونِ، في السماواتِ والأرضِ والشمسِ والقمرِ والبحارِ والجبال، وفي نفسك، في خلقك وتكوينك وأعضائك؛ لتزداد يقينًا بأنّ القرآنَ حقٌّ والله ربٌّ واحد؛ فآياتُ الله في الآفاقِ والأنفسِ شاهدةٌ على صدقِ القرآنِ وعلى عظمةِ الخالق؛ فكفى بالله شهيدًا على صدقِ رسوله وكتابه؛ أولم يكفِ بربّك أنه على كلِّ شيء شهيد؛ فاجعل تأمّلك في آياتِ الله الكونيةِ والنفسيةِ سبيلًا لزيادةِ إيمانك ويقينك؛ فمن تأمّل آياتِ الله في الآفاقِ والأنفسِ ازداد يقينًا بالحق."}},{"n":54,"reflection":{"text":"«ألا إنهم في مرية من لقاء ربهم ألا إنه بكل شيء محيط»: ألا إنّ المكذّبين في شكٍّ من لقاءِ ربّهم (البعث)، ألا إنّ الله بكلِّ شيء محيطٌ علمًا وقدرة؛ ففي هذا ذمُّ الشكِّ في البعثِ وتقريرُ إحاطةِ الله بكلِّ شيء؛ فأيقن بلقاءِ الله وبالبعث، واعلم أنّ الله محيطٌ بكلِّ شيء، فراقبه واستعدّ للقائه، فمن أيقن بلقاءِ الله وإحاطتِه استقام عمله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بلقاءِ الله والبعث، وإدراكُ إحاطتِه بكلِّ شيء."},"action":{"text":"تأمّل ختامَ السورةِ بتقريرِ البعثِ والإحاطة: ألا إنّ هؤلاء المكذّبين في مريةٍ وشكٍّ من لقاءِ ربّهم يومَ القيامةِ للبعثِ والحساب؛ ألا إنّ الله بكلِّ شيء محيطٌ علمًا وقدرةً وسلطانًا، فلا يخرج شيءٌ عن علمه وقدرته «ألا إنهم في مرية من لقاء ربهم ألا إنه بكل شيء محيط»؛ ففي هذا ذمُّ الشكِّ في لقاءِ الله والبعث، وتقريرُ إحاطةِ الله بكلِّ شيء؛ فمريةُ المكذّبين وشكّهم في البعثِ سببُ ضلالهم وفسادِ أعمالهم؛ فأيقن أنت بلقاءِ الله وبالبعثِ والحسابِ يقينًا جازمًا؛ فالإيمانُ بلقاءِ الله واليومِ الآخرِ ركنٌ من أركانِ الإيمان؛ ومن كان يرجو لقاءَ الله فإنّ أجلَ الله لآت؛ واعلم أنّ الله بكلِّ شيء محيط: أحاط علمه بكلِّ شيء، وأحاطت قدرته بكلِّ شيء، ووسع كلَّ شيءٍ رحمةً وعلمًا؛ والله من ورائهم محيط؛ فراقب الله المحيطَ بكلِّ شيء في سرّك وعلنك؛ واستعدّ للقائه بالإيمانِ والعملِ الصالح؛ فمن أيقن بلقاءِ الله وإحاطتِه بكلِّ شيء استقام عمله، وأحسن استعداده؛ ومن شكّ في اللقاءِ وغفل عن الإحاطةِ فسد عمله؛ فاجعل يقينك بلقاءِ الله وإحاطتِه حافزًا للاستقامةِ والعمل؛ فبهذا اليقينِ تُختَم السورةُ التي بدأت بتعظيمِ القرآن، لتحمل القلبَ على الاستعدادِ للقاءِ الله المحيطِ بكلِّ شيء."}}]}],"coverage":{"covered":54,"total":54}};
